window.__PAGE_RUNTIME_PARTIALS__["partials/guia-python-content.html"]  = "<button class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Men\u00fa\">&#9776;</button>\n<button class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\">&#9776;</button>\n\n<div class=\"layout app-layout\">\n  <nav class=\"sidebar\" id=\"sidebar\">\n    <div class=\"sidebar-logo\">\n      <div class=\"badge\">SENA \u00b7 FPI</div>\n      <h2>Gu\u00eda - Pr\u00e1ctica de Python</h2>\n      <p>Sistemas Teleinform\u00e1ticos \u00b7 Variables, condicionales y POO</p>\n      <button class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\">&#9664;</button>\n    </div>\n\n    <div class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\">\n      <div class=\"sf-label\">Tu grupo</div>\n      <div class=\"sf-inst\" id=\"sb-inst\"></div>\n      <div class=\"sf-meta\" id=\"sb-grupo-meta\"></div>\n      <div class=\"sf-badge\" id=\"sb-badge\"></div>\n    </div>\n    <div class=\"sidebar-noficha\" id=\"sb-ficha-warn\">\n      <a href=\"index.html\">Inicio | Seleccionar grupo / ficha</a>\n    </div>\n\n    <div class=\"progress-wrap\">\n      <div class=\"progress-label\">\n        <span>Progreso</span>\n        <span id=\"progressValue\">0%</span>\n      </div>\n      <div class=\"progress-bar-bg\">\n        <div class=\"progress-bar\" id=\"progressBar\"></div>\n      </div>\n      <p class=\"progress-note\">El avance se completa al entregar el reto integrador.</p>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Conceptos</div>\n      <a class=\"nav-link active\" href=\"#presentacion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128075;</span> Presentaci\u00f3n</a>\n      <a class=\"nav-link\" href=\"#que-es-python\" onclick=\"setActive(this)\"><span class=\"icon\">&#128013;</span> 1. \u00bfQu\u00e9 es Python?</a>\n      <a class=\"nav-link\" href=\"#variables\" onclick=\"setActive(this)\"><span class=\"icon\">&#128230;</span> 2. Variables</a>\n      <a class=\"nav-link\" href=\"#condicionales\" onclick=\"setActive(this)\"><span class=\"icon\">&#128270;</span> 3. Condicionales</a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Ejercicios</div>\n      <a class=\"nav-link\" href=\"#ejercicios\" onclick=\"setActive(this)\"><span class=\"icon\">&#128221;</span> Ejercicios 1 a 7</a>\n      <a class=\"nav-link\" href=\"#poo\" onclick=\"setActive(this)\"><span class=\"icon\">&#129513;</span> 4. POO (Ej. 8 a 10)</a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Entrega</div>\n      <a class=\"nav-link\" href=\"#reto\" onclick=\"setActive(this)\"><span class=\"icon\">&#127919;</span> Reto integrador <span class=\"check\">&#10003;</span></a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Recursos</div>\n      <a class=\"nav-link\" href=\"#python-en-linea\" onclick=\"setActive(this)\" data-python-online-practice><span class=\"icon\">&#128187;</span> Python en l\u00ednea</a>\n      <a class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"><span class=\"icon\">&#128214;</span> Glosario</a>\n    </div>\n\n    <a class=\"nav-home-link\" href=\"calendario-academico-2026.html\">&#128197; <span>Calendario 2026</span></a>\n    <a class=\"nav-home-link\" href=\"index.html\">&#127968; <span>Volver al Inicio</span></a>\n  </nav>\n\n  <div class=\"main app-main\">\n    <div class=\"topbar\">\n      <div class=\"topbar-title\"><strong>Gu\u00eda - Pr\u00e1ctica de Python</strong></div>\n      <div class=\"topbar-meta\">\n        <span class=\"meta-item\"><span>&#128013;</span><span>10 ejercicios</span></span>\n        <span class=\"meta-item\"><span>&#128197;</span><span>2026</span></span>\n        <span class=\"meta-item\"><span>&#127979;</span><span id=\"topbarCampus\">Santa B\u00e1rbara</span></span>\n      </div>\n    </div>\n\n    <div class=\"content\">\n      <div class=\"hero\" id=\"inicio\">\n        <div class=\"tag\">Gu\u00eda complementaria \u00b7 Programaci\u00f3n</div>\n        <h1>Gu\u00eda - Pr\u00e1ctica de Python</h1>\n        <p>\n          10 ejercicios progresivos para entender los conceptos b\u00e1sicos de Python:\n          <strong>qu\u00e9 es Python, los tipos de variables m\u00e1s usados, c\u00f3mo funcionan las\n          condicionales y c\u00f3mo iniciar con Programaci\u00f3n Orientada a Objetos (POO)</strong>\n          mediante ejemplos sencillos aplicados al contexto del aprendiz.\n        </p>\n        <div class=\"hero-meta\">\n          <div class=\"hero-meta-item\">&#127963; SENA &mdash; Servicio Nacional de Aprendizaje</div>\n          <div class=\"hero-meta-item\">&#128013; Python \u00b7 variables, condicionales y POO</div>\n          <div class=\"hero-meta-item\">&#127891; C\u00f3digo: 233108 \u00b7 V1</div>\n          <div class=\"hero-meta-item\">&#127979; I.E. Santa B\u00e1rbara</div>\n        </div>\n      </div>\n\n      <div id=\"presentacion\" class=\"section-title\">Presentaci\u00f3n</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e3f2fd\">&#128075;</div>\n            <div><h3>Material de apoyo para clase</h3><p>De los conceptos a la pr\u00e1ctica con c\u00f3digo</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            Esta gu\u00eda sirve como material de apoyo para explicar de forma pr\u00e1ctica qu\u00e9 es Python,\n            cu\u00e1les son los tipos de variables m\u00e1s usados, c\u00f3mo funcionan las condicionales y c\u00f3mo\n            iniciar con Programaci\u00f3n Orientada a Objetos, mediante ejemplos sencillos y progresivos.\n          </p>\n          <div class=\"info-box green\" style=\"margin-top:14px\">\n            <div class=\"label\">&#128161; Idea clave: la indentaci\u00f3n es obligatoria</div>\n            <p>En Python, los espacios al inicio de una l\u00ednea indican qu\u00e9 instrucciones pertenecen a un\n            bloque (por ejemplo, dentro de un <code>if</code>, una funci\u00f3n o una clase). Si la indentaci\u00f3n\n            est\u00e1 mal, el programa no funciona.</p>\n          </div>\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128221; C\u00f3mo usar esta gu\u00eda</div>\n            <p>Lee cada concepto, escribe y ejecuta el c\u00f3digo sugerido en tu computador (puedes usar\n            <strong>IDLE</strong>, <strong>Thonny</strong> o <strong>Visual Studio Code</strong>), y resuelve\n            el reto de cada ejercicio. Al final entregas el <strong>reto integrador</strong>.</p>\n          </div>\n          <div id=\"python-en-linea\" class=\"python-lab-wrap\" data-python-online-practice>\n            <div class=\"python-lab-intro\">\n              <div class=\"label\">&#128187; Opci\u00f3n A \u00b7 Practicar Python en l\u00ednea dentro del portal</div>\n              <p>\n                M\u00f3dulo interno opcional para estudiantes que no pueden instalar programas o trabajan en equipos\n                lentos, prestados o institucionales. Permite escribir, ejecutar, validar y descargar c\u00f3digo Python\n                sin salir del portal; no reemplaza la pr\u00e1ctica normal ni las evidencias de la gu\u00eda.\n              </p>\n              <a class=\"python-lab__btn python-lab__btn--primary\" href=\"practica-python.html\" style=\"display:inline-flex;align-items:center;text-decoration:none;margin-top:10px\">\n                Abrir pr\u00e1ctica interna\n              </a>\n            </div>\n\n            <div class=\"python-lab-backup\">\n              <div class=\"label\">&#128279; Opci\u00f3n B \u00b7 Respaldo externo</div>\n              <p>El enlace externo que ya estaba en la gu\u00eda queda solo como respaldo si el m\u00f3dulo interno no cubre un caso avanzado.</p>\n              <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\">\n                Abrir Programiz como respaldo &#8599;\n              </a>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 1. \u00bfQU\u00c9 ES PYTHON? \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"que-es-python\" class=\"section-title\">1. \u00bfQu\u00e9 es Python?</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e8f5e9\">&#128013;</div>\n            <div><h3>Explicaci\u00f3n b\u00e1sica y elementos iniciales</h3><p>Para qu\u00e9 sirve y qu\u00e9 funciones usar\u00e1s</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            <strong>Python es un lenguaje de programaci\u00f3n</strong>: un idioma que usamos para darle\n            instrucciones a un computador. Escribimos esas \u00f3rdenes en un archivo de texto con extensi\u00f3n\n            <code>.py</code> y el computador las ejecuta una por una, <strong>de arriba hacia abajo</strong>.\n          </p>\n          <p class=\"intro-text\">\n            Es uno de los lenguajes m\u00e1s usados del mundo porque su forma de escribir es <strong>clara y\n            parecida al ingl\u00e9s</strong>: se lee casi como una receta. Por eso es ideal para empezar &mdash;\n            te concentras en <em>resolver el problema</em> y no en reglas de escritura complicadas.\n          </p>\n\n          <div class=\"info-box\">\n            <div class=\"label\">&#128640; \u00bfPara qu\u00e9 se usa en el mundo real?</div>\n            <p>Automatizar tareas repetitivas, analizar datos y generar reportes, crear p\u00e1ginas web y\n            aplicaciones, inteligencia artificial y chatbots, videojuegos sencillos y soluciones para\n            empresas y colegios. Plataformas como <strong>YouTube, Instagram, Netflix y Spotify</strong>\n            usan Python en parte de sus sistemas.</p>\n          </div>\n\n          <h4 style=\"margin:18px 0 6px\">&#128075; Tu primer programa</h4>\n          <p class=\"intro-text\" style=\"margin-top:0\">Lo m\u00e1s simple es mostrar un mensaje en pantalla con la funci\u00f3n <code>print()</code>:</p>\n<pre class=\"py-code\"><span class=\"cmt\"># mi_primer_programa.py</span>\nprint(\"\u00a1Hola! Estoy aprendiendo Python.\")\nprint(\"Programa: Sistemas Teleinform\u00e1ticos\")</pre>\n          <p class=\"intro-text\" style=\"font-size:.9rem;margin-bottom:6px\">Al ejecutarlo, el computador escribe:</p>\n<pre class=\"py-code\">\u00a1Hola! Estoy aprendiendo Python.\nPrograma: Sistemas Teleinform\u00e1ticos</pre>\n\n          <div class=\"info-box green\" style=\"margin-top:14px\">\n            <div class=\"label\">&#128161; Tres reglas para no equivocarte</div>\n            <p><strong>1.</strong> Python distingue may\u00fasculas de min\u00fasculas: <code>print</code> funciona,\n            <code>Print</code> da error. &nbsp; <strong>2.</strong> El texto va siempre entre comillas:\n            <code>\"Hola\"</code>. &nbsp; <strong>3.</strong> La <em>indentaci\u00f3n</em> (los espacios al inicio de\n            una l\u00ednea) es obligatoria e indica qu\u00e9 instrucciones pertenecen a un bloque.</p>\n          </div>\n\n          <h4 style=\"margin:18px 0 4px\">Funciones y elementos que usar\u00e1s en toda la gu\u00eda</h4>\n          <p class=\"intro-text\" style=\"margin-top:0;font-size:.86rem\">Pulsa <strong>&#9654; probar</strong> en cada uno para ver el ejemplo escribirse y su resultado (o espera: se ejecutan solos al aparecer).</p>\n          <div class=\"fn-demos\" data-fn-demos>\n            <div class=\"fn-row\" data-fn=\"print\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">print()</code>\n                <span class=\"fn-row__desc\">Muestra informaci\u00f3n en pantalla.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"input\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">input()</code>\n                <span class=\"fn-row__desc\">Pide al usuario que escriba un dato (lo recibe como texto).</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"int\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">int()</code>\n                <span class=\"fn-row__desc\">Convierte un dato a n\u00famero entero.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"float\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">float()</code>\n                <span class=\"fn-row__desc\">Convierte un dato a n\u00famero decimal.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"str\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">str()</code>\n                <span class=\"fn-row__desc\">Convierte un dato a texto.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"bool\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">bool()</code>\n                <span class=\"fn-row__desc\">Representa un valor l\u00f3gico: verdadero o falso.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"type\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">type()</code>\n                <span class=\"fn-row__desc\">Indica qu\u00e9 tipo de dato tiene una variable.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"comentario\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\"># comentario</code>\n                <span class=\"fn-row__desc\">Explica el c\u00f3digo; Python no lo ejecuta.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128296; \u00bfD\u00f3nde escribo y ejecuto el c\u00f3digo?</div>\n            <p>&#128187; <strong>Con programa instalado:</strong> puedes usar <strong>IDLE</strong> (viene con Python), <strong>Thonny</strong> (muy recomendado\n            para principiantes) o <strong>Visual Studio Code</strong>. Escribe el c\u00f3digo, gu\u00e1rdalo con\n            extensi\u00f3n <code>.py</code> y ejec\u00fatalo con el bot\u00f3n <em>Run</em> o la tecla <code>F5</code>.</p>\n            <p data-python-online-practice style=\"margin-top:8px\">&#128187; <strong>Sin instalaci\u00f3n:</strong>\n            usa primero la <a href=\"practica-python.html\" style=\"color:var(--primary,#1565c0);font-weight:700\">Opci\u00f3n A, laboratorio interno del portal</a>.\n            El enlace externo queda como Opci\u00f3n B de respaldo si necesitas probar algo fuera del portal.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 2. VARIABLES \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"variables\" class=\"section-title\">2. Tipos de variables en Python</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#ede7f6\">&#128230;</div>\n            <div><h3>Tipos de datos</h3><p>Texto, n\u00fameros, l\u00f3gicos y colecciones</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            Una variable es un espacio en memoria donde se guarda informaci\u00f3n. En Python no es necesario\n            escribir el tipo de dato antes de crear la variable, porque Python lo identifica seg\u00fan el valor asignado.\n          </p>\n\n          <p class=\"intro-text\" style=\"margin-bottom:8px\"><strong>&#9654; Pulsa \"probar\"</strong> y ver\u00e1s a Python crear cada tipo de variable con su valor y su tipo (o se ejecutan en cascada al aparecer):</p>\n          <div class=\"fn-demos\" data-fn-demos>\n            <div class=\"fn-row\" data-fn=\"var_str\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">str</code><span class=\"fn-row__desc\">Texto o cadena de caracteres.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_int\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">int</code><span class=\"fn-row__desc\">N\u00famero entero.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_float\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">float</code><span class=\"fn-row__desc\">N\u00famero decimal.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_bool\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">bool</code><span class=\"fn-row__desc\">Valor l\u00f3gico: True o False.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_list\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">list</code><span class=\"fn-row__desc\">Lista ordenada y modificable.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_tuple\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">tuple</code><span class=\"fn-row__desc\">Colecci\u00f3n ordenada que no se modifica.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_dict\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">dict</code><span class=\"fn-row__desc\">Diccionario con clave y valor.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_set\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">set</code><span class=\"fn-row__desc\">Conjunto sin datos repetidos.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_none\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">None</code><span class=\"fn-row__desc\">Representa ausencia de valor.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n          </div>\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128204; Recomendaci\u00f3n</div>\n            <p>Antes de las condicionales, diferencia entre texto, n\u00famero entero, n\u00famero decimal y valor\n            l\u00f3gico: los errores m\u00e1s comunes ocurren al comparar datos de tipos diferentes.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3. CONDICIONALES \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"condicionales\" class=\"section-title\">3. Operadores y condicionales</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#fff3e0\">&#128270;</div>\n            <div><h3>Comparaci\u00f3n, l\u00f3gicos y tipos de condicional</h3><p>Para que el programa tome decisiones</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            Las condicionales permiten que un programa tome decisiones: ejecutan una acci\u00f3n solo si se\n            cumple una condici\u00f3n.\n          </p>\n          <h4 style=\"margin:14px 0 6px\">Operadores de comparaci\u00f3n <span style=\"font-weight:400;font-size:.82rem;color:#64748b\">(dan True o False) &mdash; pulsa \"probar\"</span></h4>\n          <div class=\"fn-demos\" data-fn-demos>\n            <div class=\"fn-row\" data-fn=\"op_eq\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">==</code><span class=\"fn-row__desc\">Igual a</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_ne\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">!=</code><span class=\"fn-row__desc\">Diferente de</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_gt\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">&gt;</code><span class=\"fn-row__desc\">Mayor que</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_lt\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">&lt;</code><span class=\"fn-row__desc\">Menor que</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_ge\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">&gt;=</code><span class=\"fn-row__desc\">Mayor o igual que</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_le\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">&lt;=</code><span class=\"fn-row__desc\">Menor o igual que</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n          </div>\n          <h4 style=\"margin:16px 0 6px\">Operadores l\u00f3gicos <span style=\"font-weight:400;font-size:.82rem;color:#64748b\">(combinan condiciones) &mdash; pulsa \"probar\"</span></h4>\n          <div class=\"fn-demos\" data-fn-demos>\n            <div class=\"fn-row\" data-fn=\"log_and\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">and</code><span class=\"fn-row__desc\">Todas las condiciones deben cumplirse.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"log_or\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">or</code><span class=\"fn-row__desc\">Al menos una condici\u00f3n debe cumplirse.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"log_not\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">not</code><span class=\"fn-row__desc\">Niega una condici\u00f3n.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n          </div>\n          <h4 style=\"margin:16px 0 6px\">Tipos de condicionales</h4>\n          <div class=\"table-scroll\">\n            <table class=\"data-table\">\n              <thead><tr><th>Tipo</th><th>Cu\u00e1ndo se usa</th></tr></thead>\n              <tbody>\n                <tr><td><code>if</code></td><td>Cuando solo se necesita validar una condici\u00f3n.</td></tr>\n                <tr><td><code>if - else</code></td><td>Cuando hay dos caminos posibles.</td></tr>\n                <tr><td><code>if - elif - else</code></td><td>Cuando hay varias opciones.</td></tr>\n                <tr><td>Condicional anidada</td><td>Cuando una condici\u00f3n depende de otra.</td></tr>\n                <tr><td>Condici\u00f3n compuesta</td><td>Cuando se combinan condiciones con and/or.</td></tr>\n                <tr><td>Condicional ternaria</td><td>Para una decisi\u00f3n corta en una l\u00ednea.</td></tr>\n                <tr><td><code>match - case</code></td><td>Para evaluar varias opciones de forma ordenada.</td></tr>\n              </tbody>\n            </table>\n          </div>\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#9888; Nota sobre match-case</div>\n            <p>La estructura <code>match-case</code> est\u00e1 disponible desde Python 3.10. Si el computador usa\n            una versi\u00f3n anterior, se puede reemplazar por <code>if</code>, <code>elif</code> y <code>else</code>.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 EJERCICIOS 1\u20137 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"ejercicios\" class=\"section-title\">Ejercicios pr\u00e1cticos (1 a 7)</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e0f2f1\">&#128221;</div>\n            <div><h3>Variables y condicionales</h3><p>7 ejercicios progresivos con c\u00f3digo y explicaci\u00f3n</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">1</span><span class=\"activity-title\">Registro b\u00e1sico del aprendiz</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> identificar variables tipo texto, entero, decimal y booleano.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>str, int, float, bool, print(), type()</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> crear un programa que registre los datos b\u00e1sicos de un aprendiz y muestre el tipo de dato de cada variable.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 1: Registro b\u00e1sico del aprendiz</span>\nnombre = \"Laura G\u00f3mez\"\nedad = 16\npromedio = 4.2\nmatriculado = True\n\nprint(\"=== DATOS DEL APRENDIZ ===\")\nprint(\"Nombre:\", nombre)\nprint(\"Edad:\", edad)\nprint(\"Promedio:\", promedio)\nprint(\"\u00bfEst\u00e1 matriculado?:\", matriculado)\nprint()\nprint(\"=== TIPOS DE DATOS ===\")\nprint(type(nombre))\nprint(type(edad))\nprint(type(promedio))\nprint(type(matriculado))</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>nombre</code> guarda texto \u2192 su tipo es <code>str</code>.</li>\n                <li><code>edad</code> guarda un entero \u2192 su tipo es <code>int</code>.</li>\n                <li><code>promedio</code> guarda un decimal \u2192 su tipo es <code>float</code>.</li>\n                <li><code>matriculado</code> guarda True/False \u2192 su tipo es <code>bool</code>.</li>\n                <li><code>type()</code> permite ver el tipo de dato de una variable.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Cambia los datos del aprendiz y agrega una nueva variable llamada <code>ficha</code>.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Registra los datos de un <strong>instructor</strong> usando variables: su nombre (texto), los a&ntilde;os que lleva ense&ntilde;ando (entero), su salario mensual (decimal) y si est&aacute; vinculado de planta o no (booleano). Muestra cada dato con <code>print()</code> y al final imprime el tipo de cada variable con <code>type()</code>.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj1\"></div>\n              <div data-act-std-delivery=\"retoEj1\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">2</span><span class=\"activity-title\">Edad y condicional simple</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> usar input(), int() y una condicional if para validar una edad.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>input(), int, if, comparaci\u00f3n &gt;=</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> pedir el nombre y la edad. Si tiene 15 a\u00f1os o m\u00e1s, mostrar que puede iniciar la formaci\u00f3n t\u00e9cnica.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 2: Edad y condicional simple</span>\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nedad = int(input(\"Ingrese la edad: \"))\n\nprint()\nprint(\"Aprendiz:\", nombre)\nprint(\"Edad:\", edad)\n\nif edad &gt;= 15:\n    print(\"Puede iniciar la formaci\u00f3n t\u00e9cnica.\")\n\nprint(\"Fin del programa.\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>input()</code> recibe datos del usuario como texto.</li>\n                <li><code>int()</code> convierte la edad a n\u00famero entero para poder compararla.</li>\n                <li><code>edad &gt;= 15</code> verifica si cumple la edad m\u00ednima.</li>\n                <li>Si es verdadera, Python ejecuta el mensaje indentado debajo del <code>if</code>.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega una condici\u00f3n para mostrar un mensaje cuando la edad sea menor de 15 a\u00f1os.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Pide el nombre y la nota de un aprendiz con <code>input()</code>. Convierte la nota a n&uacute;mero decimal con <code>float()</code>. Si la nota es mayor o igual a 3.5, muestra el mensaje <em>\"Nota aprobatoria\"</em>. El programa siempre debe imprimir el nombre y la nota ingresada, sin importar el resultado.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj2\"></div>\n              <div data-act-std-delivery=\"retoEj2\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3</span><span class=\"activity-title\">Nota final con if y else</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> aplicar una decisi\u00f3n con dos resultados: aprobado o no aprobado.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>float, if, else, round()</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> pedir tres notas, calcular el promedio y decir si aprob\u00f3 o no aprob\u00f3.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 3: Nota final con if y else</span>\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nnota1 = float(input(\"Ingrese la nota 1: \"))\nnota2 = float(input(\"Ingrese la nota 2: \"))\nnota3 = float(input(\"Ingrese la nota 3: \"))\n\npromedio = (nota1 + nota2 + nota3) / 3\n\nprint()\nprint(\"=== RESULTADO ===\")\nprint(\"Aprendiz:\", nombre)\nprint(\"Promedio:\", round(promedio, 2))\n\nif promedio &gt;= 3.5:\n    print(\"Estado: Aprobado\")\nelse:\n    print(\"Estado: No aprobado\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>float()</code> se usa porque las notas pueden tener decimales.</li>\n                <li>El promedio se calcula sumando las tres notas y dividiendo entre 3.</li>\n                <li><code>round(promedio, 2)</code> muestra el promedio con dos decimales.</li>\n                <li><code>else</code> se ejecuta cuando la condici\u00f3n del <code>if</code> no se cumple.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega una cuarta nota y modifica la f\u00f3rmula del promedio.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Pide dos calificaciones con <code>input()</code>, convi&eacute;rtelas a decimal con <code>float()</code> y calcula el promedio. Muestra el promedio redondeado a 2 decimales con <code>round()</code>. Si el promedio es mayor o igual a 3.5, muestra <em>\"Aprob&oacute; la evaluaci&oacute;n\"</em>; si no, <em>\"No aprob&oacute; la evaluaci&oacute;n\"</em>.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj3\"></div>\n              <div data-act-std-delivery=\"retoEj3\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">4</span><span class=\"activity-title\">Promedio, asistencia y if-elif-else</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> usar varias condiciones para clasificar el estado acad\u00e9mico.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>float, int, if, elif, else, and</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> calcular el promedio y revisar la asistencia; mostrar si aprueba, recupera, pierde por nota o por inasistencia.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 4: Promedio, asistencia y if-elif-else</span>\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nnota1 = float(input(\"Ingrese la nota 1: \"))\nnota2 = float(input(\"Ingrese la nota 2: \"))\nnota3 = float(input(\"Ingrese la nota 3: \"))\nasistencia = int(input(\"Ingrese el porcentaje de asistencia: \"))\n\npromedio = (nota1 + nota2 + nota3) / 3\n\nprint()\nprint(\"=== REPORTE ACAD\u00c9MICO ===\")\nprint(\"Aprendiz:\", nombre)\nprint(\"Promedio:\", round(promedio, 2))\nprint(\"Asistencia:\", asistencia, \"%\")\n\nif asistencia &lt; 75:\n    print(\"Estado: Perdi\u00f3 por inasistencia\")\nelif promedio &gt;= 3.5 and asistencia &gt;= 75:\n    print(\"Estado: Aprobado\")\nelif promedio &gt;= 3.0:\n    print(\"Estado: Debe recuperar\")\nelse:\n    print(\"Estado: Perdi\u00f3 por nota\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>Primero se valida la asistencia, porque afecta el resultado final.</li>\n                <li><code>elif</code> revisa otras condiciones si la anterior no se cumpli\u00f3.</li>\n                <li><code>and</code> exige que se cumplan dos condiciones a la vez.</li>\n                <li>El <code>else</code> final cubre los casos restantes.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Cambia el porcentaje m\u00ednimo de asistencia de 75 a 80 y observa c\u00f3mo cambia el resultado.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Pide la cantidad de actividades entregadas (entero) y el porcentaje de asistencia (entero). Muestra el estado con <code>if</code>, <code>elif</code>, <code>else</code> y <code>and</code>: <strong>\"Destacado\"</strong> si entreg&oacute; 5 o m&aacute;s actividades <em>y</em> tiene 90 % o m&aacute;s de asistencia \u00b7 <strong>\"Cumple\"</strong> si entreg&oacute; 5 o m&aacute;s <em>y</em> tiene al menos 75 % \u00b7 <strong>\"En proceso\"</strong> si entreg&oacute; al menos 3 \u00b7 <strong>\"Incompleto\"</strong> en cualquier otro caso.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj4\"></div>\n              <div data-act-std-delivery=\"retoEj4\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">5</span><span class=\"activity-title\">Control de entrega de actividad</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> trabajar con booleanos, None y condicionales anidadas.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>bool, None, if, else, condicional anidada</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> indicar el estado de una actividad seg\u00fan si fue entregada, si fue tarde y si tiene observaci\u00f3n.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 5: Control de entrega de actividad</span>\naprendiz = input(\"Nombre del aprendiz: \")\nactividad = input(\"Nombre de la actividad: \")\nentrego = input(\"\u00bfEntreg\u00f3 la actividad? si/no: \").lower() == \"si\"\ntarde = False\nobservacion = None\n\nif entrego:\n    respuesta_tarde = input(\"\u00bfLa entreg\u00f3 tarde? si/no: \").lower()\n    if respuesta_tarde == \"si\":\n        tarde = True\n        observacion = \"Entreg\u00f3 fuera de la fecha establecida\"\n    else:\n        observacion = \"Entrega realizada a tiempo\"\nelse:\n    observacion = \"Actividad pendiente por entregar\"\n\nprint()\nprint(\"=== ESTADO DE LA ACTIVIDAD ===\")\nprint(\"Aprendiz:\", aprendiz)\nprint(\"Actividad:\", actividad)\nprint(\"Entreg\u00f3:\", entrego)\nprint(\"Entrega tarde:\", tarde)\nprint(\"Observaci\u00f3n:\", observacion)</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>entrego</code> es booleana porque solo puede ser True o False.</li>\n                <li><code>None</code> se usa cuando una variable a\u00fan no tiene valor definido.</li>\n                <li><code>.lower()</code> convierte la respuesta a min\u00fascula (evita errores por SI, Si o si).</li>\n                <li>La condicional anidada pregunta si entreg\u00f3 tarde solo si entreg\u00f3 la actividad.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega una variable <code>calificacion</code> y mu\u00e9strala solo si el aprendiz entreg\u00f3.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Registra si un aprendiz asisti&oacute; a una pr&aacute;ctica de laboratorio (s&iacute; o no). Si asisti&oacute;, pregunta si fue puntual (s&iacute; o no): si fue puntual, la observaci&oacute;n es <em>\"Asisti&oacute; a tiempo\"</em>; si no, <em>\"Asisti&oacute; tarde\"</em>. Si no asisti&oacute;, la observaci&oacute;n queda como <code>None</code> y se muestra <em>\"Sin registro de asistencia\"</em>. Usa booleanos para <code>asistio</code> y <code>puntual</code>, y muestra todos los datos al final.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj5\"></div>\n              <div data-act-std-delivery=\"retoEj5\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">6</span><span class=\"activity-title\">Lista de actividades entregadas</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> usar listas, cantidad de elementos y verificaci\u00f3n de pertenencia.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>list, len(), in, or, not</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> guardar las actividades entregadas y verificar si tiene pendiente la actividad de Python.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 6: Lista de actividades entregadas</span>\naprendiz = \"Carlos P\u00e9rez\"\nactividades_entregadas = [\"Inducci\u00f3n\", \"Variables\", \"Condicionales\"]\nactividad_revisar = \"Python\"\n\nprint(\"=== ACTIVIDADES ENTREGADAS ===\")\nprint(\"Aprendiz:\", aprendiz)\nprint(\"Actividades:\", actividades_entregadas)\nprint(\"Cantidad de actividades:\", len(actividades_entregadas))\n\nif actividad_revisar in actividades_entregadas:\n    print(\"La actividad de Python ya fue entregada.\")\nelse:\n    print(\"La actividad de Python est\u00e1 pendiente.\")\n\nif \"Variables\" in actividades_entregadas or \"Condicionales\" in actividades_entregadas:\n    print(\"El aprendiz ya inici\u00f3 la ruta de programaci\u00f3n.\")\n\nif not \"POO\" in actividades_entregadas:\n    print(\"Todav\u00eda no ha entregado Programaci\u00f3n Orientada a Objetos.\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>Una lista guarda varios datos en una sola variable.</li>\n                <li><code>len()</code> cuenta cu\u00e1ntos elementos tiene la lista.</li>\n                <li><code>in</code> revisa si un dato est\u00e1 dentro de una lista.</li>\n                <li><code>or</code> permite que se cumpla una condici\u00f3n u otra; <code>not</code> invierte el resultado.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega la actividad <code>\"Python\"</code> a la lista y vuelve a ejecutar el programa.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea una lista con los equipos disponibles en el sal&oacute;n: <em>\"PC1\"</em>, <em>\"PC2\"</em>, <em>\"Proyector\"</em>, <em>\"Tablet\"</em>. Usando <code>len()</code>, <code>in</code>, <code>or</code> y <code>not</code>, muestra: cu&aacute;ntos equipos hay en total \u00b7 si <em>\"Proyector\"</em> est&aacute; disponible \u00b7 si <em>\"PC3\"</em> o <em>\"PC4\"</em> est&aacute;n disponibles \u00b7 si <em>\"Impresora\"</em> no est&aacute; en la lista. Agrega un mensaje claro para cada caso.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj6\"></div>\n              <div data-act-std-delivery=\"retoEj6\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">7</span><span class=\"activity-title\">Ficha con diccionario, conjunto y match-case</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> integrar estructuras de datos y una condicional match-case.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>dict, set, tuple, match-case, if anidado</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> guardar los datos en un diccionario, las evidencias en un conjunto y consultar con un men\u00fa.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 7: Ficha del aprendiz (dict, set, match-case)</span>\naprendiz = {\n    \"nombre\": \"Mar\u00eda Torres\",\n    \"grado\": \"10A\",\n    \"ficha\": 3441939,\n    \"promedio\": 4.1,\n    \"activo\": True\n}\nhorario = (\"Mi\u00e9rcoles\", \"Viernes\")\nevidencias = {\"Variables\", \"Condicionales\", \"Listas\"}\n\nprint(\"=== MEN\u00da DE CONSULTA ===\")\nprint(\"1. Ver datos del aprendiz\")\nprint(\"2. Ver horario\")\nprint(\"3. Ver evidencias entregadas\")\nprint(\"4. Ver estado final\")\nopcion = int(input(\"Seleccione una opci\u00f3n: \"))\n\nmatch opcion:\n    case 1:\n        print(\"Nombre:\", aprendiz[\"nombre\"])\n        print(\"Grado:\", aprendiz[\"grado\"])\n        print(\"Ficha:\", aprendiz[\"ficha\"])\n    case 2:\n        print(\"D\u00edas de clase:\", horario)\n    case 3:\n        print(\"Evidencias:\", evidencias)\n        if \"POO\" in evidencias:\n            print(\"Ya entreg\u00f3 Programaci\u00f3n Orientada a Objetos\")\n        else:\n            print(\"Tiene pendiente Programaci\u00f3n Orientada a Objetos\")\n    case 4:\n        if aprendiz[\"activo\"] and aprendiz[\"promedio\"] &gt;= 3.5:\n            print(\"Estado: Activo y aprobado\")\n        else:\n            print(\"Estado: Revisar situaci\u00f3n acad\u00e9mica\")\n    case _:\n        print(\"Opci\u00f3n no v\u00e1lida\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>Un diccionario guarda datos con clave y valor (nombre, grado, ficha).</li>\n                <li>Una tupla guarda datos que no se modifican, como los d\u00edas de clase.</li>\n                <li>Un conjunto <code>set</code> evita datos repetidos.</li>\n                <li><code>match-case</code> eval\u00faa la opci\u00f3n de men\u00fa; <code>case _</code> es la opci\u00f3n por defecto.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega una opci\u00f3n 5 al men\u00fa para mostrar si el aprendiz est\u00e1 activo o inactivo.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea un diccionario con los datos de un <strong>computador del aula</strong> (marca, procesador, RAM y si est&aacute; operativo), un conjunto con los programas instalados y una tupla con los horarios en que est&aacute; disponible. Muestra un men&uacute; con <code>match-case</code> de 4 opciones: <strong>1</strong> ver datos del equipo \u00b7 <strong>2</strong> ver programas instalados \u00b7 <strong>3</strong> ver horarios \u00b7 <strong>4</strong> ver si est&aacute; operativo. Cualquier otra opci&oacute;n muestra <em>\"Opci&oacute;n no v&aacute;lida\"</em>.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj7\"></div>\n              <div data-act-std-delivery=\"retoEj7\"></div>\n            </div>\n          </div>\n\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 4. POO \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"poo\" class=\"section-title\">4. Introducci\u00f3n a la Programaci\u00f3n Orientada a Objetos (POO)</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e8eaf6\">&#129513;</div>\n            <div><h3>Clases, objetos, atributos y m\u00e9todos</h3><p>Conceptos + ejercicios 8, 9 y 10</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            La POO permite organizar el c\u00f3digo usando <strong>clases</strong> y <strong>objetos</strong>. En vez\n            de tener todo el programa en instrucciones sueltas, se crean moldes que representan elementos reales\n            (por ejemplo, un estudiante, una actividad o una ficha).\n          </p>\n          <div class=\"table-scroll\">\n            <table class=\"data-table\">\n              <thead><tr><th>Concepto</th><th>Explicaci\u00f3n sencilla</th><th>Ejemplo</th></tr></thead>\n              <tbody>\n                <tr><td>Clase</td><td>Molde o plantilla para crear objetos.</td><td><code>class Estudiante:</code></td></tr>\n                <tr><td>Objeto</td><td>Elemento creado a partir de una clase.</td><td><code>estudiante1 = Estudiante(...)</code></td></tr>\n                <tr><td>Atributo</td><td>Caracter\u00edstica del objeto.</td><td><code>self.nombre</code></td></tr>\n                <tr><td>M\u00e9todo</td><td>Acci\u00f3n que puede realizar el objeto.</td><td><code>calcular_promedio()</code></td></tr>\n                <tr><td>Constructor __init__</td><td>Inicializa los atributos al crear el objeto.</td><td><code>def __init__(self, nombre):</code></td></tr>\n                <tr><td>self</td><td>Representa el objeto actual dentro de la clase.</td><td><code>self.nota1 = nota1</code></td></tr>\n              </tbody>\n            </table>\n          </div>\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128161; Forma sencilla de explicarlo</div>\n            <p>Una clase es como un formulario vac\u00edo. Cuando lo llenamos con datos reales, creamos un objeto.\n            Los datos del formulario son <strong>atributos</strong> y las acciones que puede hacer son <strong>m\u00e9todos</strong>.</p>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">8</span><span class=\"activity-title\">POO 1: Clase Estudiante</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> crear una clase con atributos, m\u00e9todos y condicionales para obtener el estado acad\u00e9mico.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>class, __init__, self, atributos, m\u00e9todos, if-else</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> clase <code>Estudiante</code> con nombre, grado y tres notas; calcula el promedio y muestra si aprob\u00f3 o no.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 8: POO 1 - Clase Estudiante</span>\nclass Estudiante:\n    def __init__(self, nombre, grado, nota1, nota2, nota3):\n        self.nombre = nombre\n        self.grado = grado\n        self.nota1 = nota1\n        self.nota2 = nota2\n        self.nota3 = nota3\n\n    def calcular_promedio(self):\n        return (self.nota1 + self.nota2 + self.nota3) / 3\n\n    def obtener_estado(self):\n        promedio = self.calcular_promedio()\n        if promedio &gt;= 3.5:\n            return \"Aprobado\"\n        else:\n            return \"No aprobado\"\n\n    def mostrar_informacion(self):\n        print(\"=== INFORMACI\u00d3N DEL ESTUDIANTE ===\")\n        print(\"Nombre:\", self.nombre)\n        print(\"Grado:\", self.grado)\n        print(\"Promedio:\", round(self.calcular_promedio(), 2))\n        print(\"Estado:\", self.obtener_estado())\n\nestudiante1 = Estudiante(\"Laura G\u00f3mez\", \"10A\", 4.0, 3.8, 4.5)\nestudiante1.mostrar_informacion()</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>class Estudiante</code> crea el molde para construir estudiantes.</li>\n                <li><code>__init__</code> recibe los datos iniciales; <code>self.nombre</code>, <code>self.grado</code>\u2026 son atributos.</li>\n                <li><code>calcular_promedio()</code> y <code>obtener_estado()</code> son m\u00e9todos (acciones).</li>\n                <li><code>estudiante1</code> es un objeto creado a partir de la clase.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega un atributo <code>asistencia</code> y modifica <code>obtener_estado()</code> para que pierda si la asistencia es menor a 75.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea una clase <code>Computador</code> con los atributos: marca (texto), velocidad del procesador en GHz (decimal) y si est&aacute; encendido (booleano). La clase debe tener un m&eacute;todo que muestre la informaci&oacute;n del equipo y otro que diga si el procesador es <em>\"R&aacute;pido\"</em> o <em>\"Lento\"</em> (r&aacute;pido si la velocidad es mayor o igual a 2.5 GHz). Crea dos objetos con datos distintos y muestra la informaci&oacute;n de cada uno.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj8\"></div>\n              <div data-act-std-delivery=\"retoEj8\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">9</span><span class=\"activity-title\">POO 2: Clase EntregaActividad</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> representar una entrega acad\u00e9mica como objeto y evaluar su estado.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>class, bool, None, if-elif-else, m\u00e9todos</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> clase que guarde la informaci\u00f3n de una actividad entregada e indique si est\u00e1 pendiente, a tiempo, tarde o aprobada.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 9: POO 2 - Clase EntregaActividad</span>\nclass EntregaActividad:\n    def __init__(self, aprendiz, actividad, entregada, tarde, nota=None):\n        self.aprendiz = aprendiz\n        self.actividad = actividad\n        self.entregada = entregada\n        self.tarde = tarde\n        self.nota = nota\n\n    def obtener_estado(self):\n        if not self.entregada:\n            return \"Pendiente por entregar\"\n        elif self.nota is None:\n            return \"Entregada, pendiente por calificar\"\n        elif self.tarde and self.nota &gt;= 3.5:\n            return \"Aprobada, pero entregada tarde\"\n        elif self.nota &gt;= 3.5:\n            return \"Aprobada\"\n        else:\n            return \"No aprobada\"\n\n    def mostrar_reporte(self):\n        print(\"=== REPORTE DE ENTREGA ===\")\n        print(\"Aprendiz:\", self.aprendiz)\n        print(\"Actividad:\", self.actividad)\n        print(\"Entregada:\", self.entregada)\n        print(\"Entrega tarde:\", self.tarde)\n        print(\"Nota:\", self.nota)\n        print(\"Estado:\", self.obtener_estado())\n\nentrega1 = EntregaActividad(\"Carlos P\u00e9rez\", \"Condicionales\", True, False, 4.2)\nentrega1.mostrar_reporte()</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>La clase <code>EntregaActividad</code> representa una evidencia acad\u00e9mica.</li>\n                <li><code>entregada</code> y <code>tarde</code> son booleanos; <code>nota=None</code> = sin calificar.</li>\n                <li><code>not self.entregada</code> verifica si no entreg\u00f3; <code>elif</code> clasifica los estados.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Crea tres objetos diferentes: una entrega aprobada, una pendiente y una entregada tarde.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea una clase <code>Asistencia</code> con los atributos: nombre del aprendiz, nombre de la sesi&oacute;n, si asisti&oacute; (bool), si lleg&oacute; tarde (bool) y justificaci&oacute;n (empieza como <code>None</code>). La clase debe tener un m&eacute;todo que determine el estado: <em>\"Inasistencia\"</em> si no asisti&oacute; \u00b7 <em>\"Asistencia tard&iacute;a\"</em> si asisti&oacute; pero lleg&oacute; tarde \u00b7 <em>\"Asistencia puntual\"</em> si asisti&oacute; a tiempo. Crea tres objetos con casos distintos y muestra el reporte de cada uno.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj9\"></div>\n              <div data-act-std-delivery=\"retoEj9\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">10</span><span class=\"activity-title\">POO 3: Clase Ficha con lista de aprendices</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> usar una clase que contenga una lista de objetos y aplique condicionales para un reporte.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>class, list, objetos, for, if, m\u00e9todos</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> clase <code>Ficha</code> que guarde varios estudiantes, muestre cu\u00e1ntos tiene y liste qui\u00e9nes est\u00e1n aprobados o en revisi\u00f3n.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 10: POO 3 - Clase Ficha con lista de aprendices</span>\nclass Estudiante:\n    def __init__(self, nombre, promedio):\n        self.nombre = nombre\n        self.promedio = promedio\n\n    def esta_aprobado(self):\n        return self.promedio &gt;= 3.5\n\nclass Ficha:\n    def __init__(self, numero, programa):\n        self.numero = numero\n        self.programa = programa\n        self.estudiantes = []\n\n    def agregar_estudiante(self, estudiante):\n        self.estudiantes.append(estudiante)\n\n    def mostrar_reporte(self):\n        print(\"=== REPORTE DE FICHA ===\")\n        print(\"Ficha:\", self.numero)\n        print(\"Programa:\", self.programa)\n        print(\"Cantidad de estudiantes:\", len(self.estudiantes))\n        for estudiante in self.estudiantes:\n            if estudiante.esta_aprobado():\n                estado = \"Aprobado\"\n            else:\n                estado = \"En revisi\u00f3n\"\n            print(estudiante.nombre, \"- Promedio:\", estudiante.promedio, \"-\", estado)\n\nficha = Ficha(3441939, \"Sistemas Teleinform\u00e1ticos\")\nficha.agregar_estudiante(Estudiante(\"Laura G\u00f3mez\", 4.3))\nficha.agregar_estudiante(Estudiante(\"Carlos P\u00e9rez\", 3.2))\nficha.agregar_estudiante(Estudiante(\"Mar\u00eda Torres\", 3.8))\nficha.mostrar_reporte()</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>Se crean dos clases: <code>Estudiante</code> y <code>Ficha</code>.</li>\n                <li>La ficha tiene n\u00famero, programa y una lista de estudiantes.</li>\n                <li><code>append()</code> agrega objetos a la lista; <code>for</code> recorre cada estudiante.</li>\n                <li>La condicional <code>if</code> decide si cada estudiante est\u00e1 aprobado o en revisi\u00f3n.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega un m\u00e9todo <code>contar_aprobados()</code> que muestre cu\u00e1ntos estudiantes aprobaron.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea dos clases: <code>Equipo</code> (con nombre del equipo y si est&aacute; operativo) y <code>Aula</code> (con nombre del aula y una lista de equipos). La clase <code>Aula</code> debe tener: un m&eacute;todo para agregar equipos a la lista con <code>append()</code>, un m&eacute;todo que muestre cu&aacute;ntos equipos hay en total y un m&eacute;todo que recorra la lista con <code>for</code> y muestre solo los equipos operativos. Crea un aula con al menos cuatro equipos y llama a cada m&eacute;todo.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj10\"></div>\n              <div data-act-std-delivery=\"retoEj10\"></div>\n            </div>\n          </div>\n\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 RETO INTEGRADOR (ENTREGA) \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"reto\" class=\"section-title\">5. Reto integrador (entrega)</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#fff8e1\">&#127919;</div>\n            <div><h3>Sistema b\u00e1sico de seguimiento acad\u00e9mico</h3><p>Aplica todo lo aprendido y entrega tu programa</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <article class=\"story-card\">\n            <h3>&#128221; Descripci\u00f3n del reto</h3>\n            <p>Crear un programa en Python que permita registrar aprendices, actividades, notas, asistencia y\n            estado de entrega. El programa debe generar un <strong>reporte final</strong> del aprendiz aplicando\n            variables, tipos de datos, condicionales, listas, diccionarios y POO.</p>\n          </article>\n\n          <div class=\"info-box\" style=\"margin-top:14px\">\n            <div class=\"label\">&#9989; Requisitos m\u00ednimos</div>\n            <p>\n              1) Clase <code>Aprendiz</code> con nombre, grado, ficha, asistencia y lista de actividades. \u00b7\n              2) Clase <code>Actividad</code> con nombre, nota, estado de entrega y observaci\u00f3n. \u00b7\n              3) Usar <code>str, int, float, bool, list, dict, set, tuple</code> y <code>None</code>. \u00b7\n              4) Usar <code>if</code>, <code>if-else</code>, <code>if-elif-else</code> y al menos una condicional anidada. \u00b7\n              5) Usar <code>and</code>, <code>or</code> y <code>not</code>. \u00b7\n              6) Crear m\u00ednimo tres objetos <code>Aprendiz</code>. \u00b7\n              7) Mostrar un reporte final con promedio, asistencia, actividades pendientes y estado acad\u00e9mico. \u00b7\n              8) Agregar un men\u00fa con <code>match-case</code> (o <code>if-elif-else</code> si la versi\u00f3n no lo permite).\n            </p>\n          </div>\n\n          <div class=\"info-box green\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128203; Reglas del reto</div>\n            <p>\n              Si promedio &gt;= 3.5 y asistencia &gt;= 75 \u2192 aprueba. \u00b7\n              Si asistencia &lt; 75 \u2192 en revisi\u00f3n por inasistencia. \u00b7\n              Si tiene actividades pendientes \u2192 el reporte debe mostrarlas. \u00b7\n              Si una actividad no tiene nota \u2192 se guarda con <code>None</code> y se muestra como pendiente por calificar. \u00b7\n              Si no tiene actividades registradas \u2192 mostrar un mensaje de advertencia.\n            </p>\n          </div>\n\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128206; Producto esperado y nombre del archivo</div>\n            <p>Entrega el archivo <strong>.py funcionando</strong> y una <strong>captura de pantalla</strong> donde\n            se vea el reporte generado. S\u00fabelo en un solo archivo (puedes comprimir el .py y la imagen en un .zip).\n            Sugerencia de nombre: <code>RetoPython_NombreAprendiz_FICHA.zip</code></p>\n          </div>\n\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128221; Criterios de evaluaci\u00f3n</div>\n            <p>Funcionamiento del programa, uso correcto de variables, uso correcto de condicionales, aplicaci\u00f3n\n            de POO, claridad del c\u00f3digo, orden en la presentaci\u00f3n y evidencia de prueba.</p>\n          </div>\n\n          <div class=\"activity open mission-card\" style=\"margin-top:16px\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">5.1</span><span class=\"activity-title\">Entrega del reto integrador (.py + captura)</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Sube tu programa <code>.py</code> funcionando y la captura del reporte que genera. El archivo se guarda autom\u00e1ticamente en la carpeta de tu ficha.</p>\n              <div data-act-std-delivery=\"retoPython\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 GLOSARIO \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"glosario\" class=\"section-title\">Glosario r\u00e1pido</div>\n      <div class=\"card\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\"><div class=\"card-icon\" style=\"background:#f3e5f5\">&#128214;</div><div><h3>Glosario</h3><p>T\u00e9rminos clave de la gu\u00eda</p></div></div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <dl class=\"glossary\">\n            <dt>Variable</dt><dd>Espacio donde se guarda un dato.</dd>\n            <dt>Dato</dt><dd>Informaci\u00f3n que puede ser texto, n\u00famero, verdadero/falso o una colecci\u00f3n.</dd>\n            <dt>Condicional</dt><dd>Estructura que permite tomar decisiones en el programa.</dd>\n            <dt>Indentaci\u00f3n</dt><dd>Espacios al inicio de una l\u00ednea que indican pertenencia a un bloque.</dd>\n            <dt>Lista</dt><dd>Colecci\u00f3n ordenada y modificable de datos.</dd>\n            <dt>Diccionario</dt><dd>Colecci\u00f3n que guarda datos con clave y valor.</dd>\n            <dt>Clase</dt><dd>Molde para crear objetos.</dd>\n            <dt>Objeto</dt><dd>Elemento creado a partir de una clase.</dd>\n            <dt>Atributo</dt><dd>Caracter\u00edstica de un objeto.</dd>\n            <dt>M\u00e9todo</dt><dd>Acci\u00f3n que puede realizar un objeto.</dd>\n          </dl>\n          <p class=\"intro-text\" style=\"font-size:.82rem;color:#607d8b;margin-top:12px\">Material de apoyo de Python \u2014 Programa Sistemas Teleinform\u00e1ticos (233108 \u00b7 V1), I.E. Santa B\u00e1rbara.</p>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</div>\n";
window.__GUIDE_RUNTIME_PARTIALS__["partials/guia-python-content.html"] = "<button class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Men\u00fa\">&#9776;</button>\n<button class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\">&#9776;</button>\n\n<div class=\"layout app-layout\">\n  <nav class=\"sidebar\" id=\"sidebar\">\n    <div class=\"sidebar-logo\">\n      <div class=\"badge\">SENA \u00b7 FPI</div>\n      <h2>Gu\u00eda - Pr\u00e1ctica de Python</h2>\n      <p>Sistemas Teleinform\u00e1ticos \u00b7 Variables, condicionales y POO</p>\n      <button class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\">&#9664;</button>\n    </div>\n\n    <div class=\"sidebar-ficha\" id=\"sb-ficha-ok\" style=\"display:none\">\n      <div class=\"sf-label\">Tu grupo</div>\n      <div class=\"sf-inst\" id=\"sb-inst\"></div>\n      <div class=\"sf-meta\" id=\"sb-grupo-meta\"></div>\n      <div class=\"sf-badge\" id=\"sb-badge\"></div>\n    </div>\n    <div class=\"sidebar-noficha\" id=\"sb-ficha-warn\">\n      <a href=\"index.html\">Inicio | Seleccionar grupo / ficha</a>\n    </div>\n\n    <div class=\"progress-wrap\">\n      <div class=\"progress-label\">\n        <span>Progreso</span>\n        <span id=\"progressValue\">0%</span>\n      </div>\n      <div class=\"progress-bar-bg\">\n        <div class=\"progress-bar\" id=\"progressBar\"></div>\n      </div>\n      <p class=\"progress-note\">El avance se completa al entregar el reto integrador.</p>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Conceptos</div>\n      <a class=\"nav-link active\" href=\"#presentacion\" onclick=\"setActive(this)\"><span class=\"icon\">&#128075;</span> Presentaci\u00f3n</a>\n      <a class=\"nav-link\" href=\"#que-es-python\" onclick=\"setActive(this)\"><span class=\"icon\">&#128013;</span> 1. \u00bfQu\u00e9 es Python?</a>\n      <a class=\"nav-link\" href=\"#variables\" onclick=\"setActive(this)\"><span class=\"icon\">&#128230;</span> 2. Variables</a>\n      <a class=\"nav-link\" href=\"#condicionales\" onclick=\"setActive(this)\"><span class=\"icon\">&#128270;</span> 3. Condicionales</a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Ejercicios</div>\n      <a class=\"nav-link\" href=\"#ejercicios\" onclick=\"setActive(this)\"><span class=\"icon\">&#128221;</span> Ejercicios 1 a 7</a>\n      <a class=\"nav-link\" href=\"#poo\" onclick=\"setActive(this)\"><span class=\"icon\">&#129513;</span> 4. POO (Ej. 8 a 10)</a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Entrega</div>\n      <a class=\"nav-link\" href=\"#reto\" onclick=\"setActive(this)\"><span class=\"icon\">&#127919;</span> Reto integrador <span class=\"check\">&#10003;</span></a>\n    </div>\n\n    <div class=\"nav-section\">\n      <div class=\"nav-label\">Recursos</div>\n      <a class=\"nav-link\" href=\"#python-en-linea\" onclick=\"setActive(this)\" data-python-online-practice><span class=\"icon\">&#128187;</span> Python en l\u00ednea</a>\n      <a class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"><span class=\"icon\">&#128214;</span> Glosario</a>\n    </div>\n\n    <a class=\"nav-home-link\" href=\"calendario-academico-2026.html\">&#128197; <span>Calendario 2026</span></a>\n    <a class=\"nav-home-link\" href=\"index.html\">&#127968; <span>Volver al Inicio</span></a>\n  </nav>\n\n  <div class=\"main app-main\">\n    <div class=\"topbar\">\n      <div class=\"topbar-title\"><strong>Gu\u00eda - Pr\u00e1ctica de Python</strong></div>\n      <div class=\"topbar-meta\">\n        <span class=\"meta-item\"><span>&#128013;</span><span>10 ejercicios</span></span>\n        <span class=\"meta-item\"><span>&#128197;</span><span>2026</span></span>\n        <span class=\"meta-item\"><span>&#127979;</span><span id=\"topbarCampus\">Santa B\u00e1rbara</span></span>\n      </div>\n    </div>\n\n    <div class=\"content\">\n      <div class=\"hero\" id=\"inicio\">\n        <div class=\"tag\">Gu\u00eda complementaria \u00b7 Programaci\u00f3n</div>\n        <h1>Gu\u00eda - Pr\u00e1ctica de Python</h1>\n        <p>\n          10 ejercicios progresivos para entender los conceptos b\u00e1sicos de Python:\n          <strong>qu\u00e9 es Python, los tipos de variables m\u00e1s usados, c\u00f3mo funcionan las\n          condicionales y c\u00f3mo iniciar con Programaci\u00f3n Orientada a Objetos (POO)</strong>\n          mediante ejemplos sencillos aplicados al contexto del aprendiz.\n        </p>\n        <div class=\"hero-meta\">\n          <div class=\"hero-meta-item\">&#127963; SENA &mdash; Servicio Nacional de Aprendizaje</div>\n          <div class=\"hero-meta-item\">&#128013; Python \u00b7 variables, condicionales y POO</div>\n          <div class=\"hero-meta-item\">&#127891; C\u00f3digo: 233108 \u00b7 V1</div>\n          <div class=\"hero-meta-item\">&#127979; I.E. Santa B\u00e1rbara</div>\n        </div>\n      </div>\n\n      <div id=\"presentacion\" class=\"section-title\">Presentaci\u00f3n</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e3f2fd\">&#128075;</div>\n            <div><h3>Material de apoyo para clase</h3><p>De los conceptos a la pr\u00e1ctica con c\u00f3digo</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            Esta gu\u00eda sirve como material de apoyo para explicar de forma pr\u00e1ctica qu\u00e9 es Python,\n            cu\u00e1les son los tipos de variables m\u00e1s usados, c\u00f3mo funcionan las condicionales y c\u00f3mo\n            iniciar con Programaci\u00f3n Orientada a Objetos, mediante ejemplos sencillos y progresivos.\n          </p>\n          <div class=\"info-box green\" style=\"margin-top:14px\">\n            <div class=\"label\">&#128161; Idea clave: la indentaci\u00f3n es obligatoria</div>\n            <p>En Python, los espacios al inicio de una l\u00ednea indican qu\u00e9 instrucciones pertenecen a un\n            bloque (por ejemplo, dentro de un <code>if</code>, una funci\u00f3n o una clase). Si la indentaci\u00f3n\n            est\u00e1 mal, el programa no funciona.</p>\n          </div>\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128221; C\u00f3mo usar esta gu\u00eda</div>\n            <p>Lee cada concepto, escribe y ejecuta el c\u00f3digo sugerido en tu computador (puedes usar\n            <strong>IDLE</strong>, <strong>Thonny</strong> o <strong>Visual Studio Code</strong>), y resuelve\n            el reto de cada ejercicio. Al final entregas el <strong>reto integrador</strong>.</p>\n          </div>\n          <div id=\"python-en-linea\" class=\"python-lab-wrap\" data-python-online-practice>\n            <div class=\"python-lab-intro\">\n              <div class=\"label\">&#128187; Opci\u00f3n A \u00b7 Practicar Python en l\u00ednea dentro del portal</div>\n              <p>\n                M\u00f3dulo interno opcional para estudiantes que no pueden instalar programas o trabajan en equipos\n                lentos, prestados o institucionales. Permite escribir, ejecutar, validar y descargar c\u00f3digo Python\n                sin salir del portal; no reemplaza la pr\u00e1ctica normal ni las evidencias de la gu\u00eda.\n              </p>\n              <a class=\"python-lab__btn python-lab__btn--primary\" href=\"practica-python.html\" style=\"display:inline-flex;align-items:center;text-decoration:none;margin-top:10px\">\n                Abrir pr\u00e1ctica interna\n              </a>\n            </div>\n\n            <div class=\"python-lab-backup\">\n              <div class=\"label\">&#128279; Opci\u00f3n B \u00b7 Respaldo externo</div>\n              <p>El enlace externo que ya estaba en la gu\u00eda queda solo como respaldo si el m\u00f3dulo interno no cubre un caso avanzado.</p>\n              <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\">\n                Abrir Programiz como respaldo &#8599;\n              </a>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 1. \u00bfQU\u00c9 ES PYTHON? \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"que-es-python\" class=\"section-title\">1. \u00bfQu\u00e9 es Python?</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e8f5e9\">&#128013;</div>\n            <div><h3>Explicaci\u00f3n b\u00e1sica y elementos iniciales</h3><p>Para qu\u00e9 sirve y qu\u00e9 funciones usar\u00e1s</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            <strong>Python es un lenguaje de programaci\u00f3n</strong>: un idioma que usamos para darle\n            instrucciones a un computador. Escribimos esas \u00f3rdenes en un archivo de texto con extensi\u00f3n\n            <code>.py</code> y el computador las ejecuta una por una, <strong>de arriba hacia abajo</strong>.\n          </p>\n          <p class=\"intro-text\">\n            Es uno de los lenguajes m\u00e1s usados del mundo porque su forma de escribir es <strong>clara y\n            parecida al ingl\u00e9s</strong>: se lee casi como una receta. Por eso es ideal para empezar &mdash;\n            te concentras en <em>resolver el problema</em> y no en reglas de escritura complicadas.\n          </p>\n\n          <div class=\"info-box\">\n            <div class=\"label\">&#128640; \u00bfPara qu\u00e9 se usa en el mundo real?</div>\n            <p>Automatizar tareas repetitivas, analizar datos y generar reportes, crear p\u00e1ginas web y\n            aplicaciones, inteligencia artificial y chatbots, videojuegos sencillos y soluciones para\n            empresas y colegios. Plataformas como <strong>YouTube, Instagram, Netflix y Spotify</strong>\n            usan Python en parte de sus sistemas.</p>\n          </div>\n\n          <h4 style=\"margin:18px 0 6px\">&#128075; Tu primer programa</h4>\n          <p class=\"intro-text\" style=\"margin-top:0\">Lo m\u00e1s simple es mostrar un mensaje en pantalla con la funci\u00f3n <code>print()</code>:</p>\n<pre class=\"py-code\"><span class=\"cmt\"># mi_primer_programa.py</span>\nprint(\"\u00a1Hola! Estoy aprendiendo Python.\")\nprint(\"Programa: Sistemas Teleinform\u00e1ticos\")</pre>\n          <p class=\"intro-text\" style=\"font-size:.9rem;margin-bottom:6px\">Al ejecutarlo, el computador escribe:</p>\n<pre class=\"py-code\">\u00a1Hola! Estoy aprendiendo Python.\nPrograma: Sistemas Teleinform\u00e1ticos</pre>\n\n          <div class=\"info-box green\" style=\"margin-top:14px\">\n            <div class=\"label\">&#128161; Tres reglas para no equivocarte</div>\n            <p><strong>1.</strong> Python distingue may\u00fasculas de min\u00fasculas: <code>print</code> funciona,\n            <code>Print</code> da error. &nbsp; <strong>2.</strong> El texto va siempre entre comillas:\n            <code>\"Hola\"</code>. &nbsp; <strong>3.</strong> La <em>indentaci\u00f3n</em> (los espacios al inicio de\n            una l\u00ednea) es obligatoria e indica qu\u00e9 instrucciones pertenecen a un bloque.</p>\n          </div>\n\n          <h4 style=\"margin:18px 0 4px\">Funciones y elementos que usar\u00e1s en toda la gu\u00eda</h4>\n          <p class=\"intro-text\" style=\"margin-top:0;font-size:.86rem\">Pulsa <strong>&#9654; probar</strong> en cada uno para ver el ejemplo escribirse y su resultado (o espera: se ejecutan solos al aparecer).</p>\n          <div class=\"fn-demos\" data-fn-demos>\n            <div class=\"fn-row\" data-fn=\"print\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">print()</code>\n                <span class=\"fn-row__desc\">Muestra informaci\u00f3n en pantalla.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"input\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">input()</code>\n                <span class=\"fn-row__desc\">Pide al usuario que escriba un dato (lo recibe como texto).</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"int\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">int()</code>\n                <span class=\"fn-row__desc\">Convierte un dato a n\u00famero entero.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"float\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">float()</code>\n                <span class=\"fn-row__desc\">Convierte un dato a n\u00famero decimal.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"str\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">str()</code>\n                <span class=\"fn-row__desc\">Convierte un dato a texto.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"bool\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">bool()</code>\n                <span class=\"fn-row__desc\">Representa un valor l\u00f3gico: verdadero o falso.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"type\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\">type()</code>\n                <span class=\"fn-row__desc\">Indica qu\u00e9 tipo de dato tiene una variable.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n            <div class=\"fn-row\" data-fn=\"comentario\">\n              <div class=\"fn-row__head\">\n                <code class=\"fn-row__name\"># comentario</code>\n                <span class=\"fn-row__desc\">Explica el c\u00f3digo; Python no lo ejecuta.</span>\n                <button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button>\n              </div>\n              <div class=\"fn-row__console\">\n                <div class=\"fn-row__line\"><span class=\"fn-row__prompt\">&gt;&gt;&gt;</span> <span class=\"fn-row__typed\" data-fn-typed></span><span class=\"fn-row__caret\"></span></div>\n                <div class=\"fn-row__out\" data-fn-result></div>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128296; \u00bfD\u00f3nde escribo y ejecuto el c\u00f3digo?</div>\n            <p>&#128187; <strong>Con programa instalado:</strong> puedes usar <strong>IDLE</strong> (viene con Python), <strong>Thonny</strong> (muy recomendado\n            para principiantes) o <strong>Visual Studio Code</strong>. Escribe el c\u00f3digo, gu\u00e1rdalo con\n            extensi\u00f3n <code>.py</code> y ejec\u00fatalo con el bot\u00f3n <em>Run</em> o la tecla <code>F5</code>.</p>\n            <p data-python-online-practice style=\"margin-top:8px\">&#128187; <strong>Sin instalaci\u00f3n:</strong>\n            usa primero la <a href=\"practica-python.html\" style=\"color:var(--primary,#1565c0);font-weight:700\">Opci\u00f3n A, laboratorio interno del portal</a>.\n            El enlace externo queda como Opci\u00f3n B de respaldo si necesitas probar algo fuera del portal.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 2. VARIABLES \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"variables\" class=\"section-title\">2. Tipos de variables en Python</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#ede7f6\">&#128230;</div>\n            <div><h3>Tipos de datos</h3><p>Texto, n\u00fameros, l\u00f3gicos y colecciones</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            Una variable es un espacio en memoria donde se guarda informaci\u00f3n. En Python no es necesario\n            escribir el tipo de dato antes de crear la variable, porque Python lo identifica seg\u00fan el valor asignado.\n          </p>\n\n          <p class=\"intro-text\" style=\"margin-bottom:8px\"><strong>&#9654; Pulsa \"probar\"</strong> y ver\u00e1s a Python crear cada tipo de variable con su valor y su tipo (o se ejecutan en cascada al aparecer):</p>\n          <div class=\"fn-demos\" data-fn-demos>\n            <div class=\"fn-row\" data-fn=\"var_str\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">str</code><span class=\"fn-row__desc\">Texto o cadena de caracteres.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_int\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">int</code><span class=\"fn-row__desc\">N\u00famero entero.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_float\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">float</code><span class=\"fn-row__desc\">N\u00famero decimal.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_bool\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">bool</code><span class=\"fn-row__desc\">Valor l\u00f3gico: True o False.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_list\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">list</code><span class=\"fn-row__desc\">Lista ordenada y modificable.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_tuple\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">tuple</code><span class=\"fn-row__desc\">Colecci\u00f3n ordenada que no se modifica.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_dict\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">dict</code><span class=\"fn-row__desc\">Diccionario con clave y valor.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_set\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">set</code><span class=\"fn-row__desc\">Conjunto sin datos repetidos.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"var_none\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">None</code><span class=\"fn-row__desc\">Representa ausencia de valor.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n          </div>\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128204; Recomendaci\u00f3n</div>\n            <p>Antes de las condicionales, diferencia entre texto, n\u00famero entero, n\u00famero decimal y valor\n            l\u00f3gico: los errores m\u00e1s comunes ocurren al comparar datos de tipos diferentes.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 3. CONDICIONALES \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"condicionales\" class=\"section-title\">3. Operadores y condicionales</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#fff3e0\">&#128270;</div>\n            <div><h3>Comparaci\u00f3n, l\u00f3gicos y tipos de condicional</h3><p>Para que el programa tome decisiones</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            Las condicionales permiten que un programa tome decisiones: ejecutan una acci\u00f3n solo si se\n            cumple una condici\u00f3n.\n          </p>\n          <h4 style=\"margin:14px 0 6px\">Operadores de comparaci\u00f3n <span style=\"font-weight:400;font-size:.82rem;color:#64748b\">(dan True o False) &mdash; pulsa \"probar\"</span></h4>\n          <div class=\"fn-demos\" data-fn-demos>\n            <div class=\"fn-row\" data-fn=\"op_eq\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">==</code><span class=\"fn-row__desc\">Igual a</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_ne\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">!=</code><span class=\"fn-row__desc\">Diferente de</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_gt\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">&gt;</code><span class=\"fn-row__desc\">Mayor que</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_lt\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">&lt;</code><span class=\"fn-row__desc\">Menor que</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_ge\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">&gt;=</code><span class=\"fn-row__desc\">Mayor o igual que</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"op_le\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">&lt;=</code><span class=\"fn-row__desc\">Menor o igual que</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n          </div>\n          <h4 style=\"margin:16px 0 6px\">Operadores l\u00f3gicos <span style=\"font-weight:400;font-size:.82rem;color:#64748b\">(combinan condiciones) &mdash; pulsa \"probar\"</span></h4>\n          <div class=\"fn-demos\" data-fn-demos>\n            <div class=\"fn-row\" data-fn=\"log_and\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">and</code><span class=\"fn-row__desc\">Todas las condiciones deben cumplirse.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"log_or\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">or</code><span class=\"fn-row__desc\">Al menos una condici\u00f3n debe cumplirse.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n            <div class=\"fn-row\" data-fn=\"log_not\"><div class=\"fn-row__head\"><code class=\"fn-row__name\">not</code><span class=\"fn-row__desc\">Niega una condici\u00f3n.</span><button type=\"button\" class=\"fn-row__play\" data-fn-play>&#9654; probar</button></div></div>\n          </div>\n          <h4 style=\"margin:16px 0 6px\">Tipos de condicionales</h4>\n          <div class=\"table-scroll\">\n            <table class=\"data-table\">\n              <thead><tr><th>Tipo</th><th>Cu\u00e1ndo se usa</th></tr></thead>\n              <tbody>\n                <tr><td><code>if</code></td><td>Cuando solo se necesita validar una condici\u00f3n.</td></tr>\n                <tr><td><code>if - else</code></td><td>Cuando hay dos caminos posibles.</td></tr>\n                <tr><td><code>if - elif - else</code></td><td>Cuando hay varias opciones.</td></tr>\n                <tr><td>Condicional anidada</td><td>Cuando una condici\u00f3n depende de otra.</td></tr>\n                <tr><td>Condici\u00f3n compuesta</td><td>Cuando se combinan condiciones con and/or.</td></tr>\n                <tr><td>Condicional ternaria</td><td>Para una decisi\u00f3n corta en una l\u00ednea.</td></tr>\n                <tr><td><code>match - case</code></td><td>Para evaluar varias opciones de forma ordenada.</td></tr>\n              </tbody>\n            </table>\n          </div>\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#9888; Nota sobre match-case</div>\n            <p>La estructura <code>match-case</code> est\u00e1 disponible desde Python 3.10. Si el computador usa\n            una versi\u00f3n anterior, se puede reemplazar por <code>if</code>, <code>elif</code> y <code>else</code>.</p>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 EJERCICIOS 1\u20137 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"ejercicios\" class=\"section-title\">Ejercicios pr\u00e1cticos (1 a 7)</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e0f2f1\">&#128221;</div>\n            <div><h3>Variables y condicionales</h3><p>7 ejercicios progresivos con c\u00f3digo y explicaci\u00f3n</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">1</span><span class=\"activity-title\">Registro b\u00e1sico del aprendiz</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> identificar variables tipo texto, entero, decimal y booleano.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>str, int, float, bool, print(), type()</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> crear un programa que registre los datos b\u00e1sicos de un aprendiz y muestre el tipo de dato de cada variable.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 1: Registro b\u00e1sico del aprendiz</span>\nnombre = \"Laura G\u00f3mez\"\nedad = 16\npromedio = 4.2\nmatriculado = True\n\nprint(\"=== DATOS DEL APRENDIZ ===\")\nprint(\"Nombre:\", nombre)\nprint(\"Edad:\", edad)\nprint(\"Promedio:\", promedio)\nprint(\"\u00bfEst\u00e1 matriculado?:\", matriculado)\nprint()\nprint(\"=== TIPOS DE DATOS ===\")\nprint(type(nombre))\nprint(type(edad))\nprint(type(promedio))\nprint(type(matriculado))</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>nombre</code> guarda texto \u2192 su tipo es <code>str</code>.</li>\n                <li><code>edad</code> guarda un entero \u2192 su tipo es <code>int</code>.</li>\n                <li><code>promedio</code> guarda un decimal \u2192 su tipo es <code>float</code>.</li>\n                <li><code>matriculado</code> guarda True/False \u2192 su tipo es <code>bool</code>.</li>\n                <li><code>type()</code> permite ver el tipo de dato de una variable.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Cambia los datos del aprendiz y agrega una nueva variable llamada <code>ficha</code>.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Registra los datos de un <strong>instructor</strong> usando variables: su nombre (texto), los a&ntilde;os que lleva ense&ntilde;ando (entero), su salario mensual (decimal) y si est&aacute; vinculado de planta o no (booleano). Muestra cada dato con <code>print()</code> y al final imprime el tipo de cada variable con <code>type()</code>.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj1\"></div>\n              <div data-act-std-delivery=\"retoEj1\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">2</span><span class=\"activity-title\">Edad y condicional simple</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> usar input(), int() y una condicional if para validar una edad.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>input(), int, if, comparaci\u00f3n &gt;=</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> pedir el nombre y la edad. Si tiene 15 a\u00f1os o m\u00e1s, mostrar que puede iniciar la formaci\u00f3n t\u00e9cnica.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 2: Edad y condicional simple</span>\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nedad = int(input(\"Ingrese la edad: \"))\n\nprint()\nprint(\"Aprendiz:\", nombre)\nprint(\"Edad:\", edad)\n\nif edad &gt;= 15:\n    print(\"Puede iniciar la formaci\u00f3n t\u00e9cnica.\")\n\nprint(\"Fin del programa.\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>input()</code> recibe datos del usuario como texto.</li>\n                <li><code>int()</code> convierte la edad a n\u00famero entero para poder compararla.</li>\n                <li><code>edad &gt;= 15</code> verifica si cumple la edad m\u00ednima.</li>\n                <li>Si es verdadera, Python ejecuta el mensaje indentado debajo del <code>if</code>.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega una condici\u00f3n para mostrar un mensaje cuando la edad sea menor de 15 a\u00f1os.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Pide el nombre y la nota de un aprendiz con <code>input()</code>. Convierte la nota a n&uacute;mero decimal con <code>float()</code>. Si la nota es mayor o igual a 3.5, muestra el mensaje <em>\"Nota aprobatoria\"</em>. El programa siempre debe imprimir el nombre y la nota ingresada, sin importar el resultado.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj2\"></div>\n              <div data-act-std-delivery=\"retoEj2\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">3</span><span class=\"activity-title\">Nota final con if y else</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> aplicar una decisi\u00f3n con dos resultados: aprobado o no aprobado.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>float, if, else, round()</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> pedir tres notas, calcular el promedio y decir si aprob\u00f3 o no aprob\u00f3.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 3: Nota final con if y else</span>\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nnota1 = float(input(\"Ingrese la nota 1: \"))\nnota2 = float(input(\"Ingrese la nota 2: \"))\nnota3 = float(input(\"Ingrese la nota 3: \"))\n\npromedio = (nota1 + nota2 + nota3) / 3\n\nprint()\nprint(\"=== RESULTADO ===\")\nprint(\"Aprendiz:\", nombre)\nprint(\"Promedio:\", round(promedio, 2))\n\nif promedio &gt;= 3.5:\n    print(\"Estado: Aprobado\")\nelse:\n    print(\"Estado: No aprobado\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>float()</code> se usa porque las notas pueden tener decimales.</li>\n                <li>El promedio se calcula sumando las tres notas y dividiendo entre 3.</li>\n                <li><code>round(promedio, 2)</code> muestra el promedio con dos decimales.</li>\n                <li><code>else</code> se ejecuta cuando la condici\u00f3n del <code>if</code> no se cumple.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega una cuarta nota y modifica la f\u00f3rmula del promedio.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Pide dos calificaciones con <code>input()</code>, convi&eacute;rtelas a decimal con <code>float()</code> y calcula el promedio. Muestra el promedio redondeado a 2 decimales con <code>round()</code>. Si el promedio es mayor o igual a 3.5, muestra <em>\"Aprob&oacute; la evaluaci&oacute;n\"</em>; si no, <em>\"No aprob&oacute; la evaluaci&oacute;n\"</em>.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj3\"></div>\n              <div data-act-std-delivery=\"retoEj3\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">4</span><span class=\"activity-title\">Promedio, asistencia y if-elif-else</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> usar varias condiciones para clasificar el estado acad\u00e9mico.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>float, int, if, elif, else, and</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> calcular el promedio y revisar la asistencia; mostrar si aprueba, recupera, pierde por nota o por inasistencia.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 4: Promedio, asistencia y if-elif-else</span>\nnombre = input(\"Ingrese el nombre del aprendiz: \")\nnota1 = float(input(\"Ingrese la nota 1: \"))\nnota2 = float(input(\"Ingrese la nota 2: \"))\nnota3 = float(input(\"Ingrese la nota 3: \"))\nasistencia = int(input(\"Ingrese el porcentaje de asistencia: \"))\n\npromedio = (nota1 + nota2 + nota3) / 3\n\nprint()\nprint(\"=== REPORTE ACAD\u00c9MICO ===\")\nprint(\"Aprendiz:\", nombre)\nprint(\"Promedio:\", round(promedio, 2))\nprint(\"Asistencia:\", asistencia, \"%\")\n\nif asistencia &lt; 75:\n    print(\"Estado: Perdi\u00f3 por inasistencia\")\nelif promedio &gt;= 3.5 and asistencia &gt;= 75:\n    print(\"Estado: Aprobado\")\nelif promedio &gt;= 3.0:\n    print(\"Estado: Debe recuperar\")\nelse:\n    print(\"Estado: Perdi\u00f3 por nota\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>Primero se valida la asistencia, porque afecta el resultado final.</li>\n                <li><code>elif</code> revisa otras condiciones si la anterior no se cumpli\u00f3.</li>\n                <li><code>and</code> exige que se cumplan dos condiciones a la vez.</li>\n                <li>El <code>else</code> final cubre los casos restantes.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Cambia el porcentaje m\u00ednimo de asistencia de 75 a 80 y observa c\u00f3mo cambia el resultado.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Pide la cantidad de actividades entregadas (entero) y el porcentaje de asistencia (entero). Muestra el estado con <code>if</code>, <code>elif</code>, <code>else</code> y <code>and</code>: <strong>\"Destacado\"</strong> si entreg&oacute; 5 o m&aacute;s actividades <em>y</em> tiene 90 % o m&aacute;s de asistencia \u00b7 <strong>\"Cumple\"</strong> si entreg&oacute; 5 o m&aacute;s <em>y</em> tiene al menos 75 % \u00b7 <strong>\"En proceso\"</strong> si entreg&oacute; al menos 3 \u00b7 <strong>\"Incompleto\"</strong> en cualquier otro caso.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj4\"></div>\n              <div data-act-std-delivery=\"retoEj4\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">5</span><span class=\"activity-title\">Control de entrega de actividad</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> trabajar con booleanos, None y condicionales anidadas.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>bool, None, if, else, condicional anidada</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> indicar el estado de una actividad seg\u00fan si fue entregada, si fue tarde y si tiene observaci\u00f3n.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 5: Control de entrega de actividad</span>\naprendiz = input(\"Nombre del aprendiz: \")\nactividad = input(\"Nombre de la actividad: \")\nentrego = input(\"\u00bfEntreg\u00f3 la actividad? si/no: \").lower() == \"si\"\ntarde = False\nobservacion = None\n\nif entrego:\n    respuesta_tarde = input(\"\u00bfLa entreg\u00f3 tarde? si/no: \").lower()\n    if respuesta_tarde == \"si\":\n        tarde = True\n        observacion = \"Entreg\u00f3 fuera de la fecha establecida\"\n    else:\n        observacion = \"Entrega realizada a tiempo\"\nelse:\n    observacion = \"Actividad pendiente por entregar\"\n\nprint()\nprint(\"=== ESTADO DE LA ACTIVIDAD ===\")\nprint(\"Aprendiz:\", aprendiz)\nprint(\"Actividad:\", actividad)\nprint(\"Entreg\u00f3:\", entrego)\nprint(\"Entrega tarde:\", tarde)\nprint(\"Observaci\u00f3n:\", observacion)</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>entrego</code> es booleana porque solo puede ser True o False.</li>\n                <li><code>None</code> se usa cuando una variable a\u00fan no tiene valor definido.</li>\n                <li><code>.lower()</code> convierte la respuesta a min\u00fascula (evita errores por SI, Si o si).</li>\n                <li>La condicional anidada pregunta si entreg\u00f3 tarde solo si entreg\u00f3 la actividad.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega una variable <code>calificacion</code> y mu\u00e9strala solo si el aprendiz entreg\u00f3.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Registra si un aprendiz asisti&oacute; a una pr&aacute;ctica de laboratorio (s&iacute; o no). Si asisti&oacute;, pregunta si fue puntual (s&iacute; o no): si fue puntual, la observaci&oacute;n es <em>\"Asisti&oacute; a tiempo\"</em>; si no, <em>\"Asisti&oacute; tarde\"</em>. Si no asisti&oacute;, la observaci&oacute;n queda como <code>None</code> y se muestra <em>\"Sin registro de asistencia\"</em>. Usa booleanos para <code>asistio</code> y <code>puntual</code>, y muestra todos los datos al final.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj5\"></div>\n              <div data-act-std-delivery=\"retoEj5\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">6</span><span class=\"activity-title\">Lista de actividades entregadas</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> usar listas, cantidad de elementos y verificaci\u00f3n de pertenencia.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>list, len(), in, or, not</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> guardar las actividades entregadas y verificar si tiene pendiente la actividad de Python.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 6: Lista de actividades entregadas</span>\naprendiz = \"Carlos P\u00e9rez\"\nactividades_entregadas = [\"Inducci\u00f3n\", \"Variables\", \"Condicionales\"]\nactividad_revisar = \"Python\"\n\nprint(\"=== ACTIVIDADES ENTREGADAS ===\")\nprint(\"Aprendiz:\", aprendiz)\nprint(\"Actividades:\", actividades_entregadas)\nprint(\"Cantidad de actividades:\", len(actividades_entregadas))\n\nif actividad_revisar in actividades_entregadas:\n    print(\"La actividad de Python ya fue entregada.\")\nelse:\n    print(\"La actividad de Python est\u00e1 pendiente.\")\n\nif \"Variables\" in actividades_entregadas or \"Condicionales\" in actividades_entregadas:\n    print(\"El aprendiz ya inici\u00f3 la ruta de programaci\u00f3n.\")\n\nif not \"POO\" in actividades_entregadas:\n    print(\"Todav\u00eda no ha entregado Programaci\u00f3n Orientada a Objetos.\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>Una lista guarda varios datos en una sola variable.</li>\n                <li><code>len()</code> cuenta cu\u00e1ntos elementos tiene la lista.</li>\n                <li><code>in</code> revisa si un dato est\u00e1 dentro de una lista.</li>\n                <li><code>or</code> permite que se cumpla una condici\u00f3n u otra; <code>not</code> invierte el resultado.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega la actividad <code>\"Python\"</code> a la lista y vuelve a ejecutar el programa.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea una lista con los equipos disponibles en el sal&oacute;n: <em>\"PC1\"</em>, <em>\"PC2\"</em>, <em>\"Proyector\"</em>, <em>\"Tablet\"</em>. Usando <code>len()</code>, <code>in</code>, <code>or</code> y <code>not</code>, muestra: cu&aacute;ntos equipos hay en total \u00b7 si <em>\"Proyector\"</em> est&aacute; disponible \u00b7 si <em>\"PC3\"</em> o <em>\"PC4\"</em> est&aacute;n disponibles \u00b7 si <em>\"Impresora\"</em> no est&aacute; en la lista. Agrega un mensaje claro para cada caso.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj6\"></div>\n              <div data-act-std-delivery=\"retoEj6\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">7</span><span class=\"activity-title\">Ficha con diccionario, conjunto y match-case</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> integrar estructuras de datos y una condicional match-case.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>dict, set, tuple, match-case, if anidado</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> guardar los datos en un diccionario, las evidencias en un conjunto y consultar con un men\u00fa.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 7: Ficha del aprendiz (dict, set, match-case)</span>\naprendiz = {\n    \"nombre\": \"Mar\u00eda Torres\",\n    \"grado\": \"10A\",\n    \"ficha\": 3441939,\n    \"promedio\": 4.1,\n    \"activo\": True\n}\nhorario = (\"Mi\u00e9rcoles\", \"Viernes\")\nevidencias = {\"Variables\", \"Condicionales\", \"Listas\"}\n\nprint(\"=== MEN\u00da DE CONSULTA ===\")\nprint(\"1. Ver datos del aprendiz\")\nprint(\"2. Ver horario\")\nprint(\"3. Ver evidencias entregadas\")\nprint(\"4. Ver estado final\")\nopcion = int(input(\"Seleccione una opci\u00f3n: \"))\n\nmatch opcion:\n    case 1:\n        print(\"Nombre:\", aprendiz[\"nombre\"])\n        print(\"Grado:\", aprendiz[\"grado\"])\n        print(\"Ficha:\", aprendiz[\"ficha\"])\n    case 2:\n        print(\"D\u00edas de clase:\", horario)\n    case 3:\n        print(\"Evidencias:\", evidencias)\n        if \"POO\" in evidencias:\n            print(\"Ya entreg\u00f3 Programaci\u00f3n Orientada a Objetos\")\n        else:\n            print(\"Tiene pendiente Programaci\u00f3n Orientada a Objetos\")\n    case 4:\n        if aprendiz[\"activo\"] and aprendiz[\"promedio\"] &gt;= 3.5:\n            print(\"Estado: Activo y aprobado\")\n        else:\n            print(\"Estado: Revisar situaci\u00f3n acad\u00e9mica\")\n    case _:\n        print(\"Opci\u00f3n no v\u00e1lida\")</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>Un diccionario guarda datos con clave y valor (nombre, grado, ficha).</li>\n                <li>Una tupla guarda datos que no se modifican, como los d\u00edas de clase.</li>\n                <li>Un conjunto <code>set</code> evita datos repetidos.</li>\n                <li><code>match-case</code> eval\u00faa la opci\u00f3n de men\u00fa; <code>case _</code> es la opci\u00f3n por defecto.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega una opci\u00f3n 5 al men\u00fa para mostrar si el aprendiz est\u00e1 activo o inactivo.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea un diccionario con los datos de un <strong>computador del aula</strong> (marca, procesador, RAM y si est&aacute; operativo), un conjunto con los programas instalados y una tupla con los horarios en que est&aacute; disponible. Muestra un men&uacute; con <code>match-case</code> de 4 opciones: <strong>1</strong> ver datos del equipo \u00b7 <strong>2</strong> ver programas instalados \u00b7 <strong>3</strong> ver horarios \u00b7 <strong>4</strong> ver si est&aacute; operativo. Cualquier otra opci&oacute;n muestra <em>\"Opci&oacute;n no v&aacute;lida\"</em>.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj7\"></div>\n              <div data-act-std-delivery=\"retoEj7\"></div>\n            </div>\n          </div>\n\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 4. POO \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"poo\" class=\"section-title\">4. Introducci\u00f3n a la Programaci\u00f3n Orientada a Objetos (POO)</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#e8eaf6\">&#129513;</div>\n            <div><h3>Clases, objetos, atributos y m\u00e9todos</h3><p>Conceptos + ejercicios 8, 9 y 10</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <p class=\"intro-text\" style=\"margin-top:0\">\n            La POO permite organizar el c\u00f3digo usando <strong>clases</strong> y <strong>objetos</strong>. En vez\n            de tener todo el programa en instrucciones sueltas, se crean moldes que representan elementos reales\n            (por ejemplo, un estudiante, una actividad o una ficha).\n          </p>\n          <div class=\"table-scroll\">\n            <table class=\"data-table\">\n              <thead><tr><th>Concepto</th><th>Explicaci\u00f3n sencilla</th><th>Ejemplo</th></tr></thead>\n              <tbody>\n                <tr><td>Clase</td><td>Molde o plantilla para crear objetos.</td><td><code>class Estudiante:</code></td></tr>\n                <tr><td>Objeto</td><td>Elemento creado a partir de una clase.</td><td><code>estudiante1 = Estudiante(...)</code></td></tr>\n                <tr><td>Atributo</td><td>Caracter\u00edstica del objeto.</td><td><code>self.nombre</code></td></tr>\n                <tr><td>M\u00e9todo</td><td>Acci\u00f3n que puede realizar el objeto.</td><td><code>calcular_promedio()</code></td></tr>\n                <tr><td>Constructor __init__</td><td>Inicializa los atributos al crear el objeto.</td><td><code>def __init__(self, nombre):</code></td></tr>\n                <tr><td>self</td><td>Representa el objeto actual dentro de la clase.</td><td><code>self.nota1 = nota1</code></td></tr>\n              </tbody>\n            </table>\n          </div>\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128161; Forma sencilla de explicarlo</div>\n            <p>Una clase es como un formulario vac\u00edo. Cuando lo llenamos con datos reales, creamos un objeto.\n            Los datos del formulario son <strong>atributos</strong> y las acciones que puede hacer son <strong>m\u00e9todos</strong>.</p>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">8</span><span class=\"activity-title\">POO 1: Clase Estudiante</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> crear una clase con atributos, m\u00e9todos y condicionales para obtener el estado acad\u00e9mico.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>class, __init__, self, atributos, m\u00e9todos, if-else</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> clase <code>Estudiante</code> con nombre, grado y tres notas; calcula el promedio y muestra si aprob\u00f3 o no.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 8: POO 1 - Clase Estudiante</span>\nclass Estudiante:\n    def __init__(self, nombre, grado, nota1, nota2, nota3):\n        self.nombre = nombre\n        self.grado = grado\n        self.nota1 = nota1\n        self.nota2 = nota2\n        self.nota3 = nota3\n\n    def calcular_promedio(self):\n        return (self.nota1 + self.nota2 + self.nota3) / 3\n\n    def obtener_estado(self):\n        promedio = self.calcular_promedio()\n        if promedio &gt;= 3.5:\n            return \"Aprobado\"\n        else:\n            return \"No aprobado\"\n\n    def mostrar_informacion(self):\n        print(\"=== INFORMACI\u00d3N DEL ESTUDIANTE ===\")\n        print(\"Nombre:\", self.nombre)\n        print(\"Grado:\", self.grado)\n        print(\"Promedio:\", round(self.calcular_promedio(), 2))\n        print(\"Estado:\", self.obtener_estado())\n\nestudiante1 = Estudiante(\"Laura G\u00f3mez\", \"10A\", 4.0, 3.8, 4.5)\nestudiante1.mostrar_informacion()</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li><code>class Estudiante</code> crea el molde para construir estudiantes.</li>\n                <li><code>__init__</code> recibe los datos iniciales; <code>self.nombre</code>, <code>self.grado</code>\u2026 son atributos.</li>\n                <li><code>calcular_promedio()</code> y <code>obtener_estado()</code> son m\u00e9todos (acciones).</li>\n                <li><code>estudiante1</code> es un objeto creado a partir de la clase.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega un atributo <code>asistencia</code> y modifica <code>obtener_estado()</code> para que pierda si la asistencia es menor a 75.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea una clase <code>Computador</code> con los atributos: marca (texto), velocidad del procesador en GHz (decimal) y si est&aacute; encendido (booleano). La clase debe tener un m&eacute;todo que muestre la informaci&oacute;n del equipo y otro que diga si el procesador es <em>\"R&aacute;pido\"</em> o <em>\"Lento\"</em> (r&aacute;pido si la velocidad es mayor o igual a 2.5 GHz). Crea dos objetos con datos distintos y muestra la informaci&oacute;n de cada uno.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj8\"></div>\n              <div data-act-std-delivery=\"retoEj8\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">9</span><span class=\"activity-title\">POO 2: Clase EntregaActividad</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> representar una entrega acad\u00e9mica como objeto y evaluar su estado.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>class, bool, None, if-elif-else, m\u00e9todos</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> clase que guarde la informaci\u00f3n de una actividad entregada e indique si est\u00e1 pendiente, a tiempo, tarde o aprobada.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 9: POO 2 - Clase EntregaActividad</span>\nclass EntregaActividad:\n    def __init__(self, aprendiz, actividad, entregada, tarde, nota=None):\n        self.aprendiz = aprendiz\n        self.actividad = actividad\n        self.entregada = entregada\n        self.tarde = tarde\n        self.nota = nota\n\n    def obtener_estado(self):\n        if not self.entregada:\n            return \"Pendiente por entregar\"\n        elif self.nota is None:\n            return \"Entregada, pendiente por calificar\"\n        elif self.tarde and self.nota &gt;= 3.5:\n            return \"Aprobada, pero entregada tarde\"\n        elif self.nota &gt;= 3.5:\n            return \"Aprobada\"\n        else:\n            return \"No aprobada\"\n\n    def mostrar_reporte(self):\n        print(\"=== REPORTE DE ENTREGA ===\")\n        print(\"Aprendiz:\", self.aprendiz)\n        print(\"Actividad:\", self.actividad)\n        print(\"Entregada:\", self.entregada)\n        print(\"Entrega tarde:\", self.tarde)\n        print(\"Nota:\", self.nota)\n        print(\"Estado:\", self.obtener_estado())\n\nentrega1 = EntregaActividad(\"Carlos P\u00e9rez\", \"Condicionales\", True, False, 4.2)\nentrega1.mostrar_reporte()</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>La clase <code>EntregaActividad</code> representa una evidencia acad\u00e9mica.</li>\n                <li><code>entregada</code> y <code>tarde</code> son booleanos; <code>nota=None</code> = sin calificar.</li>\n                <li><code>not self.entregada</code> verifica si no entreg\u00f3; <code>elif</code> clasifica los estados.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Crea tres objetos diferentes: una entrega aprobada, una pendiente y una entregada tarde.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea una clase <code>Asistencia</code> con los atributos: nombre del aprendiz, nombre de la sesi&oacute;n, si asisti&oacute; (bool), si lleg&oacute; tarde (bool) y justificaci&oacute;n (empieza como <code>None</code>). La clase debe tener un m&eacute;todo que determine el estado: <em>\"Inasistencia\"</em> si no asisti&oacute; \u00b7 <em>\"Asistencia tard&iacute;a\"</em> si asisti&oacute; pero lleg&oacute; tarde \u00b7 <em>\"Asistencia puntual\"</em> si asisti&oacute; a tiempo. Crea tres objetos con casos distintos y muestra el reporte de cada uno.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj9\"></div>\n              <div data-act-std-delivery=\"retoEj9\"></div>\n            </div>\n          </div>\n\n          <div class=\"activity open\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">10</span><span class=\"activity-title\">POO 3: Clase Ficha con lista de aprendices</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n                            <div data-programiz-link style=\"display:none;margin-bottom:10px\">\n                <a href=\"https://www.programiz.com/python-programming/online-compiler/\" target=\"_blank\" rel=\"noopener noreferrer\"\n                   style=\"display:inline-flex;align-items:center;gap:6px;background:#e8f5e9;border:1.5px solid #43a047;border-radius:8px;padding:8px 14px;color:#2e7d32;font-weight:700;text-decoration:none;font-size:.97em\">\n                  &#9654; Opci\u00f3n B \u00b7 Programiz como respaldo &#8599;\n                </a>\n                <span style=\"display:block;font-size:.82em;color:#555;margin-top:4px\">&#128204; Respaldo externo: usa primero la Opci\u00f3n A interna del portal cuando est\u00e9 habilitada.</span>\n              </div>\n              <p class=\"intro-text\" style=\"margin-top:0\"><strong>Objetivo:</strong> usar una clase que contenga una lista de objetos y aplique condicionales para un reporte.</p>\n              <div class=\"info-box\"><div class=\"label\">&#129513; Conceptos</div><p>class, list, objetos, for, if, m\u00e9todos</p></div>\n              <p class=\"intro-text\"><strong>Enunciado:</strong> clase <code>Ficha</code> que guarde varios estudiantes, muestre cu\u00e1ntos tiene y liste qui\u00e9nes est\u00e1n aprobados o en revisi\u00f3n.</p>\n<pre class=\"py-code\"><span class=\"cmt\"># Ejercicio 10: POO 3 - Clase Ficha con lista de aprendices</span>\nclass Estudiante:\n    def __init__(self, nombre, promedio):\n        self.nombre = nombre\n        self.promedio = promedio\n\n    def esta_aprobado(self):\n        return self.promedio &gt;= 3.5\n\nclass Ficha:\n    def __init__(self, numero, programa):\n        self.numero = numero\n        self.programa = programa\n        self.estudiantes = []\n\n    def agregar_estudiante(self, estudiante):\n        self.estudiantes.append(estudiante)\n\n    def mostrar_reporte(self):\n        print(\"=== REPORTE DE FICHA ===\")\n        print(\"Ficha:\", self.numero)\n        print(\"Programa:\", self.programa)\n        print(\"Cantidad de estudiantes:\", len(self.estudiantes))\n        for estudiante in self.estudiantes:\n            if estudiante.esta_aprobado():\n                estado = \"Aprobado\"\n            else:\n                estado = \"En revisi\u00f3n\"\n            print(estudiante.nombre, \"- Promedio:\", estudiante.promedio, \"-\", estado)\n\nficha = Ficha(3441939, \"Sistemas Teleinform\u00e1ticos\")\nficha.agregar_estudiante(Estudiante(\"Laura G\u00f3mez\", 4.3))\nficha.agregar_estudiante(Estudiante(\"Carlos P\u00e9rez\", 3.2))\nficha.agregar_estudiante(Estudiante(\"Mar\u00eda Torres\", 3.8))\nficha.mostrar_reporte()</pre>\n              <p class=\"intro-text\" style=\"font-size:.9rem\"><strong>Explicaci\u00f3n:</strong></p>\n              <ul class=\"py-list\">\n                <li>Se crean dos clases: <code>Estudiante</code> y <code>Ficha</code>.</li>\n                <li>La ficha tiene n\u00famero, programa y una lista de estudiantes.</li>\n                <li><code>append()</code> agrega objetos a la lista; <code>for</code> recorre cada estudiante.</li>\n                <li>La condicional <code>if</code> decide si cada estudiante est\u00e1 aprobado o en revisi\u00f3n.</li>\n              </ul>\n              <div class=\"info-box green\"><div class=\"label\">&#127919; Reto</div><p>Agrega un m\u00e9todo <code>contar_aprobados()</code> que muestre cu\u00e1ntos estudiantes aprobaron.</p></div>\n              <div class=\"info-box\" style=\"background:#f9f0ff;border-left:4px solid #7b1fa2;margin-top:10px\">\n                <div class=\"label\" style=\"color:#6a1b9a\">&#128161; Ejercicio adicional \u2014 pi&eacute;nsalo t&uacute;</div>\n                <p>Crea dos clases: <code>Equipo</code> (con nombre del equipo y si est&aacute; operativo) y <code>Aula</code> (con nombre del aula y una lista de equipos). La clase <code>Aula</code> debe tener: un m&eacute;todo para agregar equipos a la lista con <code>append()</code>, un m&eacute;todo que muestre cu&aacute;ntos equipos hay en total y un m&eacute;todo que recorra la lista con <code>for</code> y muestre solo los equipos operativos. Crea un aula con al menos cuatro equipos y llama a cada m&eacute;todo.</p>\n              </div>\n              <div data-act-std-delivery=\"adicionalEj10\"></div>\n              <div data-act-std-delivery=\"retoEj10\"></div>\n            </div>\n          </div>\n\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 RETO INTEGRADOR (ENTREGA) \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"reto\" class=\"section-title\">5. Reto integrador (entrega)</div>\n      <div class=\"card open\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\">\n            <div class=\"card-icon\" style=\"background:#fff8e1\">&#127919;</div>\n            <div><h3>Sistema b\u00e1sico de seguimiento acad\u00e9mico</h3><p>Aplica todo lo aprendido y entrega tu programa</p></div>\n          </div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <article class=\"story-card\">\n            <h3>&#128221; Descripci\u00f3n del reto</h3>\n            <p>Crear un programa en Python que permita registrar aprendices, actividades, notas, asistencia y\n            estado de entrega. El programa debe generar un <strong>reporte final</strong> del aprendiz aplicando\n            variables, tipos de datos, condicionales, listas, diccionarios y POO.</p>\n          </article>\n\n          <div class=\"info-box\" style=\"margin-top:14px\">\n            <div class=\"label\">&#9989; Requisitos m\u00ednimos</div>\n            <p>\n              1) Clase <code>Aprendiz</code> con nombre, grado, ficha, asistencia y lista de actividades. \u00b7\n              2) Clase <code>Actividad</code> con nombre, nota, estado de entrega y observaci\u00f3n. \u00b7\n              3) Usar <code>str, int, float, bool, list, dict, set, tuple</code> y <code>None</code>. \u00b7\n              4) Usar <code>if</code>, <code>if-else</code>, <code>if-elif-else</code> y al menos una condicional anidada. \u00b7\n              5) Usar <code>and</code>, <code>or</code> y <code>not</code>. \u00b7\n              6) Crear m\u00ednimo tres objetos <code>Aprendiz</code>. \u00b7\n              7) Mostrar un reporte final con promedio, asistencia, actividades pendientes y estado acad\u00e9mico. \u00b7\n              8) Agregar un men\u00fa con <code>match-case</code> (o <code>if-elif-else</code> si la versi\u00f3n no lo permite).\n            </p>\n          </div>\n\n          <div class=\"info-box green\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128203; Reglas del reto</div>\n            <p>\n              Si promedio &gt;= 3.5 y asistencia &gt;= 75 \u2192 aprueba. \u00b7\n              Si asistencia &lt; 75 \u2192 en revisi\u00f3n por inasistencia. \u00b7\n              Si tiene actividades pendientes \u2192 el reporte debe mostrarlas. \u00b7\n              Si una actividad no tiene nota \u2192 se guarda con <code>None</code> y se muestra como pendiente por calificar. \u00b7\n              Si no tiene actividades registradas \u2192 mostrar un mensaje de advertencia.\n            </p>\n          </div>\n\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128206; Producto esperado y nombre del archivo</div>\n            <p>Entrega el archivo <strong>.py funcionando</strong> y una <strong>captura de pantalla</strong> donde\n            se vea el reporte generado. S\u00fabelo en un solo archivo (puedes comprimir el .py y la imagen en un .zip).\n            Sugerencia de nombre: <code>RetoPython_NombreAprendiz_FICHA.zip</code></p>\n          </div>\n\n          <div class=\"info-box\" style=\"margin-top:12px\">\n            <div class=\"label\">&#128221; Criterios de evaluaci\u00f3n</div>\n            <p>Funcionamiento del programa, uso correcto de variables, uso correcto de condicionales, aplicaci\u00f3n\n            de POO, claridad del c\u00f3digo, orden en la presentaci\u00f3n y evidencia de prueba.</p>\n          </div>\n\n          <div class=\"activity open mission-card\" style=\"margin-top:16px\">\n            <div class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\">\n              <span class=\"activity-num\">5.1</span><span class=\"activity-title\">Entrega del reto integrador (.py + captura)</span><span class=\"activity-toggle\">&#9662;</span>\n            </div>\n            <div class=\"activity-body\">\n              <p class=\"intro-text\" style=\"margin-top:0\">Sube tu programa <code>.py</code> funcionando y la captura del reporte que genera. El archivo se guarda autom\u00e1ticamente en la carpeta de tu ficha.</p>\n              <div data-act-std-delivery=\"retoPython\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 GLOSARIO \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 -->\n      <div id=\"glosario\" class=\"section-title\">Glosario r\u00e1pido</div>\n      <div class=\"card\">\n        <div class=\"card-header\" onclick=\"toggleCard(this.parentElement)\">\n          <div class=\"card-header-left\"><div class=\"card-icon\" style=\"background:#f3e5f5\">&#128214;</div><div><h3>Glosario</h3><p>T\u00e9rminos clave de la gu\u00eda</p></div></div>\n          <span class=\"card-toggle\">&#9662;</span>\n        </div>\n        <div class=\"card-body\">\n          <dl class=\"glossary\">\n            <dt>Variable</dt><dd>Espacio donde se guarda un dato.</dd>\n            <dt>Dato</dt><dd>Informaci\u00f3n que puede ser texto, n\u00famero, verdadero/falso o una colecci\u00f3n.</dd>\n            <dt>Condicional</dt><dd>Estructura que permite tomar decisiones en el programa.</dd>\n            <dt>Indentaci\u00f3n</dt><dd>Espacios al inicio de una l\u00ednea que indican pertenencia a un bloque.</dd>\n            <dt>Lista</dt><dd>Colecci\u00f3n ordenada y modificable de datos.</dd>\n            <dt>Diccionario</dt><dd>Colecci\u00f3n que guarda datos con clave y valor.</dd>\n            <dt>Clase</dt><dd>Molde para crear objetos.</dd>\n            <dt>Objeto</dt><dd>Elemento creado a partir de una clase.</dd>\n            <dt>Atributo</dt><dd>Caracter\u00edstica de un objeto.</dd>\n            <dt>M\u00e9todo</dt><dd>Acci\u00f3n que puede realizar un objeto.</dd>\n          </dl>\n          <p class=\"intro-text\" style=\"font-size:.82rem;color:#607d8b;margin-top:12px\">Material de apoyo de Python \u2014 Programa Sistemas Teleinform\u00e1ticos (233108 \u00b7 V1), I.E. Santa B\u00e1rbara.</p>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</div>\n";
